// Fiches spécifiques pour les missions biodiversité historiques.
[['La biodiversité comprend la diversité des espèces, des individus d’une même espèce et des milieux.', 'Un être vivant naît, grandit, se nourrit, peut se reproduire et finit par mourir.', 'Une plante est vivante même si elle ne se déplace pas ; l’eau et les roches ne sont pas des êtres vivants.'], ['Classer consiste à regrouper selon les caractères possédés en commun.', 'Les insectes adultes ont six pattes ; les araignées ont huit pattes ; les mammifères ont des poils ; les oiseaux ont des plumes.', 'Les groupes sont emboîtés : un mammifère appartient aussi au groupe des vertébrés. Le lieu de vie ne suffit pas pour classer.'], ['Un écosystème comprend un milieu, les êtres vivants qui y vivent et leurs relations.', 'Une mare abrite des plantes, des animaux adultes et des larves qui n’ont pas tous le même rôle.', 'La lumière, l’eau, la température et les relations alimentaires influencent la vie dans la mare.'], ['Une flèche alimentaire part de l’être vivant mangé vers celui qui le mange : elle signifie « est mangé par ».', 'Les végétaux verts sont des producteurs primaires. Les animaux sont des consommateurs.', 'Plusieurs chaînes reliées forment un réseau alimentaire : une modification peut toucher plusieurs espèces.'], ['La destruction des habitats, les pollutions et certaines introductions d’espèces menacent la biodiversité.', 'Préserver des haies, des plantes locales, l’eau et des passages entre habitats peut aider les espèces.', 'On observe les animaux sans les déranger et on mène les actions de restauration avec des adultes et du matériel adapté.']].forEach((points, i) => MISSIONS[i].lesson = points);
function chapter(subject, name, lesson, items) {
  const subjectInfo = SUBJECTS.find(s => s.id === subject),
    m = MISSIONS.length;
  MISSIONS.push({
    name,
    subject,
    icon: subjectInfo.icon,
    color: subjectInfo.color,
    place: subjectInfo.world,
    badge: 'Mission « ' + name + ' »',
    intro: lesson[0],
    lesson
  });
  items.forEach((item, n) => {
    const [type, prompt, options, correct, explanation, extra = {}] = item;
    add(m, type, prompt, options, correct, explanation, {
      difficulty: n > 3 ? 2 : 1,
      hint: lesson[1],
      ...extra
    });
  });
  return m;
}
// Ces constructeurs explicitent la réponse de chaque activité ; aucune réponse libre n'est notée.
const MC = (p, right, wrong, e, extra = {}) => ['qcm', p, [right, ...wrong], [0], e, extra];
const TF = (p, yes, e) => ['tf', p, ['Vrai', 'Faux'], [yes ? 0 : 1], e];
const NUM = (p, n, e, unit = '') => ['number', p, [], [n], e, {
  unit
}];
const PAIR = (p, left, right, e) => ['match', p, left, left.map((_, i) => i), e, {
  targets: right
}];
const SORT = (p, cards, groups, correct, e) => ['sort', p, cards, correct, e, {
  groups
}];
const ORDER = (p, steps, e) => ['order', p, steps, steps.map((_, i) => i), e];
const FREE = (p, model, extra = {}) => ['definition', p, [], ['model'], model, extra];
const GAP = (p, sentence, words, e) => ['blanks', p, words, words.map((_, i) => i), e, {
  sentence
}];
const MULTI = (p, options, correct, e) => ['multi', p, options, correct, e];

// MATHÉMATIQUES — nombres, calcul, problèmes, mesures, espace, données et probabilités.
chapter('maths', 'Les grands nombres', ['Dans l’écriture d’un entier, chaque chiffre a une valeur liée à sa position.', 'Les classes de trois chiffres aident à lire : unités, milliers, millions.', 'Pour comparer, compare d’abord le nombre de chiffres puis chaque rang de gauche à droite.'], [MC('Dans 5 307 214, que vaut le chiffre 3 ?', '300 000', ['3 000', '30 000', '3 000 000'], 'Le 3 est au rang des centaines de milliers : il vaut 300 000.'), NUM('Écris en chiffres : deux millions quarante mille six.', 2040006, '2 millions + 40 milliers + 6 unités = 2 040 006.'), MC('Quel nombre est le plus grand ?', '7 090 000', ['7 009 000', '709 000', '7 089 999'], 'Les trois premiers chiffres significatifs permettent de comparer : 7 090 000 dépasse 7 089 999.'), ORDER('Range du plus petit au plus grand.', ['98 750', '98 999', '99 001', '100 000'], 'Compare les rangs de gauche à droite : 98 750 < 98 999 < 99 001 < 100 000.'), PAIR('Associe le nombre à sa décomposition.', ['45 208', '405 208', '4 005 208'], ['40 000 + 5 000 + 200 + 8', '400 000 + 5 000 + 200 + 8', '4 000 000 + 5 000 + 200 + 8'], 'Un zéro garde la place d’un rang dans lequel il n’y a aucune unité.'), TF('Dans 80 406, le chiffre des centaines est 4.', true, 'En partant de la droite : 6 unités, 0 dizaine, 4 centaines, 0 millier et 8 dizaines de milliers.'), NUM('Quel entier vient juste après 999 999 ?', 1000000, 'Ajouter une unité à 999 999 donne 1 000 000.'), FREE('Explique comment lire et comparer 2 400 050 et 2 040 500.', 'Les deux nombres ont 2 millions. On compare ensuite les centaines de milliers : 4 contre 0. Donc 2 400 050 est plus grand.')]);
chapter('maths', 'Les fractions', ['Une fraction représente un partage en parts égales ou un nombre sur une droite.', 'Dans 3/4, le dénominateur 4 indique quatre parts égales ; le numérateur 3 en désigne trois.', 'Deux fractions peuvent représenter le même nombre : 1/2 = 2/4.'], [MC('Un disque est partagé en 8 parts égales. Trois sont coloriées. Quelle fraction est coloriée ?', '3/8', ['8/3', '3/5', '8/8'], 'Le tout est partagé en 8 parts égales et 3 sont coloriées.'), MC('Quelle fraction est égale à 1/2 ?', '4/8', ['1/8', '2/3', '3/4'], '4 parts sur 8 représentent la moitié du tout.'), MC('Quelle fraction est plus grande que 1 ?', '7/4', ['3/4', '1/4', '4/4'], '7 quarts représentent un entier et 3 quarts. 4/4 vaut exactement 1.'), MC('Calcule : 2/7 + 3/7.', '5/7', ['5/14', '6/7', '1/7'], 'Les parts ont la même taille : 2 septièmes + 3 septièmes = 5 septièmes.'), ORDER('Range ces fractions du plus petit au plus grand.', ['1/5', '2/5', '4/5', '6/5'], 'À dénominateur égal, plus le numérateur est grand, plus la fraction est grande.'), PAIR('Associe les écritures équivalentes.', ['1/2', '3/4', '5/4'], ['2/4', '6/8', '1 + 1/4'], 'On peut partager chaque part en deux sans changer la quantité représentée.'), NUM('Combien font les trois quarts de 20 billes ?', 15, 'Un quart de 20 vaut 5. Trois quarts valent 3 × 5 = 15.', 'billes'), FREE('Explique pourquoi 5/3 est plus grand que 1.', 'Un entier contient 3 tiers. Avec 5 tiers, on a un entier et encore 2 tiers : 5/3 = 1 + 2/3.')]);
chapter('maths', 'Les nombres décimaux', ['Les dixièmes et centièmes prolongent les rangs à droite de la virgule.', '0,4 = 4/10 et 0,04 = 4/100.', 'Ajouter un zéro à droite de la partie décimale ne change pas le nombre : 2,5 = 2,50.'], [NUM('Écris en nombre décimal : 3 + 7/10 + 2/100.', 3.72, '3 unités, 7 dixièmes et 2 centièmes s’écrivent 3,72.'), MC('Quel nombre est le plus grand ?', '4,8', ['4,75', '4,08', '4,079'], '4,8 = 4,80. 80 centièmes sont plus grands que 75 centièmes.'), TF('2,50 et 2,5 désignent le même nombre.', true, '50 centièmes valent 5 dixièmes : 2,50 = 2,5.'), PAIR('Relie les fractions décimales à leur écriture.', ['7/10', '7/100', '125/100'], ['0,7', '0,07', '1,25'], 'Le dénominateur 10 correspond aux dixièmes et 100 aux centièmes.'), ORDER('Range les nombres décimaux dans l’ordre croissant.', ['0,09', '0,9', '0,99', '1,09'], 'On compare d’abord les unités, puis les dixièmes, puis les centièmes.'), NUM('Quel est le chiffre des centièmes de 8,364 ?', 6, 'Après la virgule : 3 dixièmes, 6 centièmes et 4 millièmes.'), MC('Entre quels entiers consécutifs se trouve 12,75 ?', '12 et 13', ['11 et 12', '13 et 14', '10 et 11'], '12 < 12,75 < 13.'), FREE('Pourquoi 0,8 est-il plus grand que 0,75 ?', '0,8 est égal à 0,80. On compare 80 centièmes à 75 centièmes : 80 > 75.')]);
chapter('maths', 'Calcul mental et priorités utiles', ['Cherche des décompositions simples et des compléments à 10, 100 ou 1 000.', 'Multiplier par 10 donne un nombre dix fois plus grand ; chaque chiffre change de rang.', 'Les parenthèses indiquent un calcul à faire d’abord.'], [NUM('Calcule mentalement : 25 × 4.', 100, '25 + 25 + 25 + 25 = 100.'), NUM('Calcule : 3,6 × 10.', 36, '3,6 contient 36 dixièmes. Dix fois plus donne 36 unités.'), NUM('Calcule : 480 ÷ 10.', 48, 'Diviser par 10 donne un nombre dix fois plus petit.'), NUM('Calcule : 250 + 75 + 50.', 375, 'On peut regrouper 250 et 50 : 300 + 75 = 375.'), NUM('Calcule : 1 000 − 398.', 602, '1 000 − 400 = 600 ; on a retiré 2 de trop, donc on ajoute 2.'), NUM('Calcule : (8 + 2) × 6.', 60, 'On commence par les parenthèses : 8 + 2 = 10, puis 10 × 6 = 60.'), TF('Multiplier un nombre par 0,5 revient à en prendre la moitié.', true, '0,5 = 1/2 : multiplier par 0,5 revient à diviser par 2.'), FREE('Propose une méthode pour calculer 19 × 5 mentalement.', 'On peut calculer 20 × 5 = 100 puis retirer 5 : 19 × 5 = 95.')]);
chapter('maths', 'Addition, soustraction et multiplication', ['Pour poser une addition ou une soustraction, aligne les unités avec les unités.', 'Avec les décimaux, les virgules sont alignées.', 'Un ordre de grandeur permet de vérifier si le résultat est plausible.'], [NUM('Calcule : 3 486 + 2 759.', 6245, '3 486 + 2 759 = 6 245. Pense aux retenues.'), NUM('Calcule : 7 003 − 2 846.', 4157, '7 003 − 2 846 = 4 157. Les échanges permettent de soustraire à travers les zéros.'), NUM('Calcule : 247 × 6.', 1482, '200 × 6 + 40 × 6 + 7 × 6 = 1 200 + 240 + 42 = 1 482.'), NUM('Calcule : 36 × 24.', 864, '36 × 20 = 720 et 36 × 4 = 144. La somme vaut 864.'), NUM('Calcule : 12,75 + 3,8.', 16.55, '12,75 + 3,80 = 16,55.'), NUM('Calcule : 9,2 − 4,65.', 4.55, '9,20 − 4,65 = 4,55.'), MC('Quel ordre de grandeur convient à 198 × 21 ?', '4 000', ['400', '40', '40 000'], '198 est proche de 200 et 21 de 20 : 200 × 20 = 4 000.'), FREE('Explique pourquoi il faut aligner les virgules pour additionner 3,7 et 12,45.', 'On additionne des unités de même rang : unités avec unités, dixièmes avec dixièmes et centièmes avec centièmes. 3,70 + 12,45 = 16,15.')]);
chapter('maths', 'Diviser et partager', ['La division peut chercher la taille de chaque part ou le nombre de parts.', 'Dans une division euclidienne : dividende = diviseur × quotient + reste.', 'Le reste est toujours plus petit que le diviseur.'], [NUM('Calcule : 864 ÷ 8.', 108, '8 × 108 = 864, donc 864 ÷ 8 = 108.'), MC('Dans la division euclidienne de 47 par 6, quel est le quotient ?', '7', ['6', '8', '5'], '47 = 6 × 7 + 5. Le quotient est 7 et le reste est 5.'), NUM('Quel est le reste de la division euclidienne de 53 par 5 ?', 3, '53 = 5 × 10 + 3. Le reste 3 est inférieur à 5.'), NUM('On partage équitablement 96 cartes entre 4 enfants. Combien chacun reçoit-il de cartes ?', 24, '96 ÷ 4 = 24. On vérifie : 4 × 24 = 96.', 'cartes'), NUM('On range 125 livres dans des cartons de 10 livres au maximum. Combien de cartons faut-il au minimum ?', 13, '12 cartons contiennent 120 livres. Les 5 derniers livres demandent un treizième carton.', 'cartons'), NUM('Calcule : 7,5 ÷ 3.', 2.5, '75 dixièmes partagés en 3 donnent 25 dixièmes, soit 2,5.'), TF('Le reste peut être égal au diviseur dans une division euclidienne terminée.', false, 'Si le reste est égal au diviseur, on peut encore former une part. Le reste doit donc être strictement plus petit.'), FREE('Explique pourquoi 43 = 5 × 8 + 3 vérifie une division de 43 par 5.', 'Le diviseur est 5, le quotient est 8 et le reste est 3. Le reste est inférieur à 5, donc la division est terminée.')]);
chapter('maths', 'Problèmes à plusieurs étapes', ['Lis la question avant de choisir les informations utiles.', 'Un dessin, un schéma ou un calcul intermédiaire peut aider.', 'Vérifie que ta réponse correspond à la question et indique son unité.'], [NUM('Une école achète 4 lots de 12 cahiers, puis distribue 15 cahiers. Combien en reste-t-il ?', 33, '4 × 12 = 48 cahiers. 48 − 15 = 33 cahiers.', 'cahiers'), NUM('Trois billets coûtent 8 € chacun. On paie avec 50 €. Combien doit-on rendre ?', 26, '3 × 8 = 24 €, puis 50 − 24 = 26 €.', '€'), NUM('Un bus peut transporter 50 élèves. Pour 128 élèves, combien de bus faut-il au minimum ?', 3, 'Deux bus transportent 100 élèves. Un troisième bus est nécessaire pour les 28 autres.', 'bus'), MC('Un texte donne l’âge du conducteur et la distance entre deux villes. Pour calculer la durée avec la vitesse, quelle donnée est inutile ?', 'L’âge du conducteur', ['La distance', 'La vitesse', 'L’unité de durée recherchée'], 'L’âge du conducteur ne sert pas à calculer cette durée.'), ORDER('Dans un problème d’achat, on connaît quantité, prix unitaire et somme payée. Organise la méthode pour trouver la monnaie.', ['Repérer la quantité et le prix unitaire', 'Calculer le prix total', 'Soustraire le prix total à la somme payée', 'Écrire la monnaie rendue avec son unité'], 'Les étapes suivent la dépendance des calculs : le prix total doit être connu avant la monnaie.'), NUM('Un trajet comporte 2,4 km à pied puis 3,75 km à vélo. Quelle est la distance totale ?', 6.15, '2,40 + 3,75 = 6,15 km.', 'km'), TF('Un résultat trouvé à la calculatrice doit quand même être vérifié avec le sens du problème.', true, 'Une erreur de saisie ou de choix d’opération est possible. Le contexte et l’ordre de grandeur permettent de vérifier.'), FREE('Une boîte de 6 œufs coûte 2 €. Combien coûtent 18 œufs ? Explique les étapes.', '18 œufs représentent 3 boîtes de 6. Chaque boîte coûte 2 €, donc 3 × 2 = 6 €.')]);
chapter('maths', 'Proportionnalité et pourcentages', ['Dans une situation proportionnelle, multiplier une quantité par un nombre multiplie l’autre par ce même nombre.', 'On peut passer par la valeur pour une unité.', '50 % signifie une moitié et 25 % un quart.'], [NUM('Trois carnets identiques coûtent 6 €. Combien coûtent 5 carnets au même prix unitaire ?', 10, 'Un carnet coûte 6 ÷ 3 = 2 €. Cinq carnets coûtent 5 × 2 = 10 €.', '€'), NUM('Pour 4 personnes, une recette utilise 300 g de riz. Quelle masse faut-il pour 8 personnes ?', 600, 'Le nombre de personnes double, donc la masse de riz double : 600 g.', 'g'), NUM('Combien font 50 % de 80 ?', 40, '50 % est la moitié : 80 ÷ 2 = 40.'), NUM('Combien font 25 % de 60 ?', 15, '25 % est un quart : 60 ÷ 4 = 15.'), MC('Quelle situation est proportionnelle ?', 'Le prix de cahiers identiques sans réduction', ['L’âge et la taille d’un enfant', 'L’âge et le poids d’un enfant', 'Le numéro d’une maison et sa taille'], 'Sans frais fixe ni réduction, chaque cahier ajoute le même prix.'), NUM('Sur une carte, 1 cm représente 2 km. Quelle distance représentent 4 cm ?', 8, '4 × 2 = 8 km.', 'km'), TF('Si deux quantités augmentent toutes les deux, elles sont forcément proportionnelles.', false, 'L’âge et la taille augmentent, mais doubler l’âge ne double pas toujours la taille.'), FREE('Deux stylos identiques coûtent 3 €. Explique comment trouver le prix de 6 stylos.', '6 stylos, c’est trois fois 2 stylos. Le prix est donc trois fois 3 €, soit 9 €.')]);
chapter('maths', 'Longueurs, masses, contenances et durées', ['Choisis une unité adaptée : mètre pour une longueur, gramme pour une masse, litre pour une contenance.', '1 km = 1 000 m ; 1 kg = 1 000 g ; 1 L = 100 cL.', 'Attention : 1 heure = 60 minutes et non 100 minutes.'], [NUM('Convertis 3,5 km en mètres.', 3500, '3,5 × 1 000 = 3 500 m.', 'm'), NUM('Convertis 2,4 kg en grammes.', 2400, '2,4 × 1 000 = 2 400 g.', 'g'), NUM('Convertis 75 cL en litres.', 0.75, '75 cL = 75/100 L = 0,75 L.', 'L'), NUM('Combien de minutes représentent 2 h 15 min ?', 135, '2 × 60 + 15 = 135 minutes.', 'min'), NUM('Un film commence à 14 h 35 et se termine à 16 h 05. Quelle est sa durée en minutes ?', 90, 'De 14 h 35 à 15 h 35 : 60 minutes. Puis 30 minutes jusqu’à 16 h 05. Total : 90 minutes.', 'min'), PAIR('Choisis l’unité adaptée.', ['La longueur d’un crayon', 'La masse d’un sac de farine', 'La contenance d’une bouteille'], ['Centimètre', 'Kilogramme', 'Litre'], 'On mesure une longueur, une masse et une contenance avec des unités différentes.'), TF('1 h 30 min est égal à 1,30 h.', false, '30 minutes est une demi-heure : 1 h 30 min = 1,5 h.'), FREE('Explique comment convertir 2 m 35 cm en centimètres.', '2 m font 200 cm. On ajoute 35 cm : 200 + 35 = 235 cm.')]);
chapter('maths', 'Périmètres et aires', ['Le périmètre mesure la longueur du contour. L’aire mesure la surface.', 'Un rectangle de longueur L et largeur l a pour périmètre 2 × (L + l).', 'Son aire est L × l ; si les côtés sont en cm, l’aire est en cm².'], [NUM('Un rectangle mesure 8 cm sur 3 cm. Quel est son périmètre ?', 22, '8 + 3 + 8 + 3 = 22 cm.', 'cm'), NUM('Quelle est l’aire d’un rectangle de 8 cm sur 3 cm ?', 24, '8 × 3 = 24 cm².', 'cm²'), NUM('Un carré a un côté de 5 cm. Quel est son périmètre ?', 20, '4 × 5 = 20 cm.', 'cm'), NUM('Un carré a un côté de 5 cm. Quelle est son aire ?', 25, '5 × 5 = 25 cm².', 'cm²'), MC('Quelle unité convient pour l’aire d’une salle ?', 'Le mètre carré', ['Le mètre', 'Le litre', 'Le kilogramme'], 'Une aire se mesure en unités carrées, ici en mètres carrés.'), TF('Deux rectangles de même périmètre ont forcément la même aire.', false, 'Un rectangle 5 × 1 et un rectangle 4 × 2 ont un périmètre de 12, mais des aires de 5 et 8.'), NUM('Deux rectangles sans chevauchement ont des aires de 12 cm² et 8 cm². Quelle est l’aire totale ?', 20, 'Les aires s’ajoutent lorsqu’il n’y a pas de chevauchement : 12 + 8 = 20.', 'cm²'), FREE('Comment distinguer l’aire et le périmètre d’un terrain ?', 'Le périmètre correspond à la longueur de la clôture autour du terrain. L’aire correspond à la surface à l’intérieur du terrain.')]);
chapter('maths', 'Droites, angles et figures', ['Des droites perpendiculaires se coupent à angle droit ; des parallèles ne se rencontrent pas dans le plan.', 'Un angle aigu est plus petit qu’un angle droit ; un angle obtus est plus grand qu’un angle droit et plus petit qu’un angle plat.', 'Carrés, rectangles, losanges et triangles se reconnaissent à leurs propriétés.'], [MC('Deux droites se coupent à angle droit. Elles sont…', 'perpendiculaires', ['parallèles', 'confondues', 'courbes'], 'L’angle droit caractérise les droites perpendiculaires.'), MC('Quel instrument permet de vérifier un angle droit ?', 'Une équerre', ['Une balance', 'Un chronomètre', 'Un verre gradué'], 'L’équerre comporte un angle droit qui sert à vérifier ou tracer des perpendiculaires.'), MC('Un triangle a trois côtés égaux. Il est…', 'équilatéral', ['rectangle obligatoirement', 'quelconque sans propriété', 'un quadrilatère'], 'Un triangle équilatéral a trois côtés de même longueur.'), SORT('Classe ces angles selon leur description.', ['Plus petit qu’un angle droit', 'Exactement un angle droit', 'Plus grand qu’un angle droit et plus petit qu’un angle plat'], ['Aigu', 'Droit', 'Obtus'], [0, 1, 2], 'On compare chaque angle à l’angle droit.'), TF('Un carré est aussi un rectangle.', true, 'Le carré possède quatre angles droits : il vérifie donc les propriétés d’un rectangle, avec en plus quatre côtés égaux.'), PAIR('Associe chaque figure à sa propriété.', ['Rectangle', 'Losange', 'Cercle'], ['Quatre angles droits', 'Quatre côtés de même longueur', 'Points à la même distance du centre'], 'Un cercle est défini par son centre et son rayon ; un losange n’a pas nécessairement des angles droits.'), MC('Pour tracer un cercle de rayon 3 cm, quelle ouverture du compas faut-il ?', '3 cm', ['6 cm', '1,5 cm', '9 cm'], 'L’ouverture du compas correspond au rayon, pas au diamètre.'), FREE('Sur une feuille, trace un rectangle de 6 cm sur 3 cm. Comment vérifier ton dessin ?', 'Je mesure deux côtés voisins : 6 cm et 3 cm. Je vérifie les quatre angles droits avec l’équerre et les côtés opposés de même longueur.', {
  practice: true
})]);
chapter('maths', 'Symétrie, solides et déplacements', ['Une symétrie axiale correspond à un pliage le long d’un axe.', 'Un cube possède 6 faces carrées, 12 arêtes et 8 sommets.', 'Pour décrire un déplacement, précise le point de départ, la direction et le nombre de cases.'], [NUM('Combien de faces possède un cube ?', 6, 'Le cube est limité par six faces carrées.', 'faces'), NUM('Combien de sommets possède un cube ?', 8, 'Un cube possède huit sommets, les points où se rejoignent les arêtes.', 'sommets'), MC('Quel dessin peut être un patron de cube ?', 'Six carrés reliés qui se replient sans se superposer', ['Un seul disque', 'Trois triangles séparés', 'Deux rectangles seulement'], 'Un patron doit permettre de former les six faces du cube par pliage.'), TF('Dans une symétrie, une figure et son image gardent les mêmes longueurs.', true, 'La symétrie conserve les longueurs et les angles.'), PAIR('Relie le solide à ses faces.', ['Cube', 'Pavé droit non cubique', 'Pyramide à base carrée'], ['Six faces carrées', 'Six faces rectangulaires, dont certaines non carrées', 'Une base carrée et quatre faces triangulaires'], 'Le cube est un cas particulier de pavé droit. On décrit les solides par leurs faces.'), NUM('Sur un quadrillage, tu pars de la colonne 2 et avances de 4 cases vers la droite. À quelle colonne arrives-tu ?', 6, '2 + 4 = 6.'), ORDER('Organise le tracé du symétrique d’un point par rapport à une droite.', ['Tracer la perpendiculaire à l’axe passant par le point', 'Repérer le pied de cette perpendiculaire sur l’axe', 'Mesurer la distance du point à l’axe', 'Reporter la même distance de l’autre côté sur la perpendiculaire'], 'Le point et son symétrique se trouvent à la même distance de l’axe.'), FREE('Construis une petite suite d’instructions pour aller de la case (1 ; 1) à la case (4 ; 3), sans diagonale.', 'Par exemple : avancer de 3 cases vers la droite, puis de 2 cases vers le haut. Les coordonnées de départ et d’arrivée doivent correspondre.', {
  practice: true
})]);
chapter('maths', 'Tableaux, graphiques et hasard', ['Un tableau ou un graphique organise des données. Vérifie les titres et les unités.', 'Un événement certain se produit à coup sûr ; un événement impossible ne peut pas se produire.', 'Avec des objets tirés au hasard dans les mêmes conditions, certaines couleurs peuvent être plus probables que d’autres.'], [NUM('Une classe a lu 6 livres lundi, 9 mardi et 5 mercredi. Combien en tout ?', 20, '6 + 9 + 5 = 20 livres.', 'livres'), MC('Voici les prêts : lundi 6, mardi 9, mercredi 5. Quel jour y a-t-il eu le plus de prêts ?', 'Mardi', ['Lundi', 'Mercredi', 'Les trois jours autant'], '9 est plus grand que 6 et 5.'), MC('Un sac contient seulement 4 jetons rouges. Tirer un jeton bleu est…', 'impossible', ['certain', 'aussi probable que rouge', 'obligatoire'], 'Aucun jeton bleu n’est présent dans le sac.'), MC('Un sac contient 8 jetons rouges et 2 bleus identiques au toucher. Quelle couleur a le plus de chances d’être tirée ?', 'Rouge', ['Bleu', 'Les deux à égalité', 'Impossible à comparer'], 'Il y a plus de jetons rouges : ils sont plus nombreux parmi les issues possibles.'), TF('Avec un dé équilibré à six faces, obtenir un nombre entre 1 et 6 est certain.', true, 'Toutes les faces portent un nombre entre 1 et 6.'), PAIR('Classe les résultats possibles d’un dé ordinaire à six faces.', ['Obtenir 7', 'Obtenir un nombre de 1 à 6', 'Obtenir 4'], ['Impossible', 'Certain', 'Possible, mais pas certain'], 'Un résultat possible peut arriver sans être garanti.'), NUM('Un graphique indique 12 vélos et 8 trottinettes. Combien de vélos de plus que de trottinettes ?', 4, '12 − 8 = 4.', 'vélos'), FREE('Pourquoi faut-il lire l’échelle d’un graphique avant de comparer les hauteurs ?', 'Un carreau peut représenter une unité, dix unités ou une autre quantité. Sans l’échelle, on ne peut pas connaître correctement les valeurs.')]);

// FRANÇAIS — textes originaux, compréhension, langue, écriture, littérature et oral.
chapter('francais', 'Lire entre les lignes', ['Une information peut être écrite clairement ou se déduire d’indices.', 'Un pronom reprend souvent un nom déjà présent.', 'Pour justifier une réponse, cite un indice du texte et explique le lien.'], [MC('« Inès replia son parapluie en entrant. Ses bottes laissaient des traces humides. » Que peut-on déduire ?', 'Il pleuvait probablement dehors.', ['Il faisait forcément nuit.', 'Inès sortait de la piscine.', 'Il neigeait forcément.'], 'Le parapluie et les bottes humides sont deux indices de pluie.'), MC('« Nox aperçoit une mésange. Elle se pose sur une branche. » Qui est « elle » ?', 'La mésange', ['Nox', 'La branche', 'Une renarde'], 'Le pronom féminin singulier « elle » reprend « une mésange ».'), MC('« Sami range sa gourde, vérifie ses lacets et rejoint le sentier. » Quel titre convient ?', 'Prêt pour la randonnée', ['Une recette de cuisine', 'Une leçon de natation', 'La réparation d’un vélo'], 'La gourde, les lacets et le sentier évoquent une randonnée.'), ORDER('Remets le petit récit dans l’ordre.', ['Mila sème une graine.', 'Elle l’arrose régulièrement.', 'Une petite pousse apparaît.', 'La plante développe plusieurs feuilles.'], 'La chronologie suit la croissance de la plante.'), TF('Une déduction doit s’appuyer sur des indices du texte.', true, 'On ne devine pas au hasard : on relie des informations présentes dans le texte à ses connaissances.'), MC('« Pourtant, Léo continua sa route. » Le mot « pourtant » annonce…', 'une opposition à ce qui précède', ['une liste d’objets', 'une date exacte', 'une définition'], '« Pourtant » marque un contraste entre deux idées.'), PAIR('Relie le connecteur à son rôle.', ['D’abord', 'Parce que', 'Cependant'], ['Indiquer une première étape', 'Donner une cause', 'Marquer une opposition'], 'Les connecteurs aident à comprendre les relations entre les idées.'), FREE('Lis : « La porte claqua. Tom sursauta et serra son doudou. » Quelle émotion Tom peut-il ressentir ? Justifie.', 'Tom peut ressentir de la peur ou de la surprise. Il sursaute et serre son doudou : ces indices justifient cette interprétation.')]);
chapter('francais', 'Textes et documents', ['Un récit raconte ; un documentaire informe ; une consigne explique ce qu’il faut faire.', 'Dans un document, lis les titres, les légendes et les données.', 'Distingue une information vérifiable d’un jugement personnel.'], [MC('« Verse la farine, ajoute l’eau puis mélange. » Ce texte sert surtout à…', 'donner des instructions', ['raconter un rêve', 'décrire une bataille', 'faire un portrait'], 'Les verbes indiquent les actions à réaliser dans une recette.'), MC('Document : « Bibliothèque : mardi 16 h–18 h ; samedi 10 h–12 h. » Quand peut-on y aller ?', 'Samedi à 11 h', ['Mardi à 15 h', 'Samedi à 14 h', 'Dimanche à 11 h'], '11 h est compris entre 10 h et 12 h le samedi.'), MC('Quelle phrase exprime une opinion ?', 'Ce roman est le plus beau de tous.', ['Ce livre compte 120 pages.', 'Le personnage s’appelle Nina.', 'Le récit comporte dix chapitres.'], '« Le plus beau » est un jugement personnel, contrairement aux informations vérifiables sur le livre.'), PAIR('Associe le document à son usage.', ['Un plan', 'Un dictionnaire', 'Un horaire de train'], ['Se repérer dans un lieu', 'Trouver le sens d’un mot', 'Connaître une heure de départ'], 'On choisit un document selon la question à laquelle on cherche une réponse.'), TF('Une légende d’image peut apporter des informations utiles à la compréhension.', true, 'Une légende identifie ou explique ce que montre une image.'), SORT('Classe les textes selon leur fonction principale.', ['Un conte d’aventure', 'Une notice de montage', 'Une fiche sur les volcans', 'Une recette'], ['Raconter', 'Faire agir', 'Informer'], [0, 1, 2, 1], 'La notice et la recette guident des actions ; le conte raconte ; la fiche documentaire informe.'), MC('Une fiche annonce : « Le hérisson est surtout actif la nuit. » Quel intertitre convient ?', 'Son mode de vie', ['Son prix', 'Les horaires du musée', 'Le menu du restaurant'], 'Le moment d’activité fait partie du mode de vie de l’animal.'), FREE('Crée une petite affiche pour annoncer une exposition à l’école. Quelles informations faut-il y mettre ?', 'Mon affiche comporte un titre, le lieu, la date, les horaires et le sujet de l’exposition. Les informations importantes sont faciles à repérer.', {
  practice: true
})]);
chapter('francais', 'Les classes de mots', ['La classe grammaticale est la nature d’un mot : nom, verbe, déterminant, adjectif, pronom, adverbe, préposition ou conjonction.', 'La classe d’un mot ne doit pas être confondue avec sa fonction dans une phrase.', 'Le contexte aide à identifier les mots dont la classe peut varier.'], [MC('Dans « Le petit renard avance », quelle est la classe de « renard » ?', 'Un nom', ['Un verbe', 'Une préposition', 'Un déterminant'], '« Renard » désigne un animal : c’est un nom commun.'), MC('Dans « Les enfants jouent », quelle est la classe de « jouent » ?', 'Un verbe', ['Un adjectif', 'Un nom', 'Un pronom'], '« Jouent » est une forme conjuguée du verbe jouer.'), SORT('Classe les mots dans « Cette grande forêt abrite un écureuil ».', ['Cette', 'grande', 'forêt', 'abrite', 'un', 'écureuil'], ['Déterminant', 'Adjectif', 'Nom', 'Verbe'], [0, 1, 2, 3, 0, 2], 'Les déterminants accompagnent les noms, l’adjectif précise le nom et le verbe est conjugué.'), PAIR('Associe chaque mot en contexte à sa classe.', ['« Elle » arrive.', 'Il court « vite ».', 'Le sac est « sous » la table.'], ['Pronom personnel', 'Adverbe', 'Préposition'], '« Elle » remplace un nom ; « vite » précise le verbe ; « sous » introduit un groupe.'), MC('Dans « Léa et Sami lisent », « et » est…', 'une conjonction de coordination', ['un verbe', 'un article', 'un adjectif'], '« Et » relie ici deux noms.'), TF('Un adjectif peut apporter une précision sur un nom.', true, 'Dans « une rivière calme », « calme » précise le nom « rivière ».'), MC('Dans « Je prends mon livre », « mon » est…', 'un déterminant possessif', ['un pronom personnel', 'un nom propre', 'un verbe'], '« Mon » accompagne « livre » et indique un lien de possession.'), FREE('Donne une phrase avec un nom, un déterminant et un adjectif, puis repère-les.', 'Par exemple : « La petite chouette dort. » La = déterminant ; chouette = nom ; petite = adjectif.')]);
chapter('francais', 'Sujet, verbe et compléments', ['Le sujet indique de qui ou de quoi on parle avec le verbe ; il commande son accord.', 'Le COD complète directement le verbe ; le COI est introduit par une préposition.', 'Les compléments circonstanciels donnent par exemple le lieu, le temps ou la manière.'], [MC('Quel est le sujet dans « Les jeunes explorateurs observent la mare » ?', 'Les jeunes explorateurs', ['observent', 'la mare', 'jeunes'], '« Ils observent » : le groupe sujet peut être remplacé par « ils ».'), MC('Quel est le verbe conjugué dans « Chaque matin, Léa nourrit les poules » ?', 'nourrit', ['Chaque matin', 'Léa', 'les poules'], 'En changeant le temps, on obtient « Léa nourrissait » : « nourrit » est le verbe.'), MC('Dans « Sami lit un roman », quel est le COD ?', 'un roman', ['Sami', 'lit', 'aucun complément'], 'Sami lit quoi ? Un roman. Le complément n’est pas introduit par une préposition.'), MC('Dans « Nora parle à sa sœur », quel est le COI ?', 'à sa sœur', ['Nora', 'parle', 'sœur seulement'], 'Le groupe « à sa sœur » complète le verbe parler avec la préposition « à ».'), SORT('Classe les groupes soulignés décrits.', ['« Hier », nous avons marché.', 'Nous marchons « dans la forêt ».', 'Elle répond « avec calme ».'], ['Temps', 'Lieu', 'Manière'], [0, 1, 2], 'Ces compléments précisent quand, où et comment se déroule l’action.'), TF('Le sujet se trouve toujours juste devant le verbe.', false, 'Il peut en être séparé ou se trouver après le verbe : « Dans le ciel brillent les étoiles. »'), PAIR('Relie la fonction à sa description.', ['Sujet', 'COD', 'Complément circonstanciel de lieu'], ['Commande l’accord du verbe', 'Complète directement le verbe', 'Précise où se déroule l’action'], 'La fonction décrit le rôle d’un mot ou d’un groupe dans la phrase.'), FREE('Dans « Demain, les élèves visiteront le musée », repère sujet, verbe et complément de temps.', 'Le sujet est « les élèves », le verbe est « visiteront » et le complément circonstanciel de temps est « Demain ».')]);
chapter('francais', 'Phrases simples et complexes', ['Une phrase simple comporte une seule proposition ; une phrase complexe en comporte plusieurs.', 'Des propositions peuvent être juxtaposées, coordonnées ou subordonnées.', 'La ponctuation et les mots de liaison rendent les relations plus claires.'], [MC('Quelle phrase contient deux verbes conjugués ?', 'Le ciel s’assombrit et la pluie arrive.', ['La pluie tombe doucement.', 'Les enfants ouvrent leurs parapluies.', 'Le ciel est gris.'], '« S’assombrit » et « arrive » sont deux verbes conjugués : la phrase contient deux propositions.'), MC('« Je reste à l’abri parce qu’il pleut. » Quelle relation exprime « parce que » ?', 'La cause', ['La comparaison de tailles', 'Le lieu', 'L’ordre alphabétique'], 'La pluie est la cause du fait de rester à l’abri.'), MC('« Le vent souffle ; les feuilles s’envolent. » Les propositions sont…', 'juxtaposées', ['reliées par « parce que »', 'une seule proposition', 'sans verbe'], 'Le point-virgule sépare deux propositions sans mot de liaison.'), TF('« Je chante et je danse » est une phrase complexe.', true, 'Elle comporte deux propositions, avec les verbes « chante » et « danse », coordonnées par « et ».'), PAIR('Relie les phrases à leur type.', ['La mare est calme.', 'La mare est calme, les oiseaux chantent.', 'La mare est calme parce que le vent est tombé.'], ['Simple', 'Complexe avec juxtaposition', 'Complexe avec subordination'], 'On repère les verbes conjugués puis la manière dont les propositions sont reliées.'), MC('Quelle phrase pose une question directe ?', 'Où habites-tu ?', ['Tu habites ici.', 'Habite ici !', 'Tu habites près de la mare.'], 'L’inversion du sujet et le point d’interrogation indiquent une question directe.'), MC('Quelle phrase contient une négation ?', 'Je ne vois plus le renard.', ['Je vois le renard.', 'Vois-tu le renard ?', 'Regarde le renard !'], '« Ne… plus » marque ici la négation.'), FREE('Relie ces deux idées par une cause : « Je prends une gourde. Il fait chaud. »', 'Je prends une gourde parce qu’il fait chaud. Le mot de liaison explique la cause du choix.')]);
chapter('francais', 'Accords et orthographe grammaticale', ['Dans le groupe nominal, déterminants et adjectifs s’accordent avec le nom.', 'Le verbe s’accorde avec son sujet, même quand un autre groupe les sépare.', 'Avec être, le participe passé s’accorde généralement avec le sujet dans les exemples simples étudiés.'], [MC('Choisis l’écriture correcte.', 'Les petites fleurs jaunes', ['Les petit fleur jaune', 'Les petites fleur jaunes', 'Les petite fleurs jaune'], 'Le nom « fleurs » est féminin pluriel : déterminant et adjectifs portent les marques correspondantes.'), MC('Complète : « Les enfants de ma voisine … dans le jardin. »', 'jouent', ['joue', 'jouons', 'jouez'], 'Le sujet est « Les enfants de ma voisine », remplaçable par « ils » : ils jouent.'), MC('Complète : « Léa et Zoé sont … tôt. »', 'arrivées', ['arrivé', 'arrivée', 'arrivés'], 'Avec l’auxiliaire être, « arrivées » s’accorde avec le sujet féminin pluriel Léa et Zoé.'), SORT('Classe les groupes nominaux.', ['un grand arbre', 'des grandes branches', 'une feuille verte', 'des grands arbres'], ['Masculin singulier', 'Féminin pluriel', 'Féminin singulier', 'Masculin pluriel'], [0, 1, 2, 3], 'Les marques du déterminant, du nom et de l’adjectif indiquent le genre et le nombre.'), TF('Dans « Mes deux frères aiment lire », le verbe doit être au pluriel.', true, 'Le sujet « Mes deux frères » est pluriel : on écrit « aiment ».'), MC('Quel est le pluriel correct de « un animal sauvage » ?', 'des animaux sauvages', ['des animals sauvages', 'des animaux sauvage', 'des animal sauvages'], 'Le pluriel d’animal est animaux. L’adjectif sauvage prend un s.'), GAP('Complète les accords.', 'Les ___ ___ poussent près du chemin.', ['petites', 'plantes'], 'Le nom plantes est féminin pluriel et l’adjectif petites s’accorde avec lui.'), FREE('Réécris au pluriel : « La grande maison est ancienne. »', 'Les grandes maisons sont anciennes. Le déterminant, le nom, les adjectifs et le verbe changent pour s’accorder au pluriel.')]);
chapter('francais', 'Homophones et mots difficiles', ['Des homophones se prononcent de la même façon mais ne s’écrivent pas toujours pareil.', 'Un remplacement peut aider : a → avait, est → était, sont → étaient.', 'Le sens et la classe grammaticale permettent de choisir une écriture.'], [MC('Complète : « Nox … une boussole. »', 'a', ['à', 'as', 'ah'], 'On peut dire « Nox avait une boussole » : il s’agit du verbe avoir.'), MC('Complète : « Il marche … la rivière. »', 'vers', ['vert', 'verre', 'ver'], '« Vers » indique une direction.'), MC('Complète : « Les oiseaux … dans le nid. »', 'sont', ['son', 'sons', 's’on'], 'On peut remplacer par « étaient » : c’est le verbe être.'), MC('Complète : « Je prends mon sac … ma gourde. »', 'et', ['est', 'es', 'ai'], '« Et » relie les deux groupes ; ce n’est pas le verbe être.'), PAIR('Associe chaque mot à un exemple.', ['ou', 'où', 'on'], ['Thé ou chocolat ?', 'Le lieu où je vis', 'On observe la mare.'], '« Ou » indique un choix ; « où » un lieu dans cet exemple ; « on » est un pronom.'), TF('« Ces » et « ses » ont toujours le même sens.', false, '« Ces » désigne ; « ses » exprime un lien de possession : ces chaussures, ses chaussures.'), MC('Quelle phrase est correctement écrite ?', 'Ils ont rangé leurs affaires.', ['Ils on rangé leurs affaires.', 'Ils ont ranger leur affaires.', 'Ils on ranger leurs affaire.'], '« Ont » est le verbe avoir ; « rangé » est le participe passé ; affaires est au pluriel.'), FREE('Explique comment choisir entre « a » et « à ».', 'Je tente de remplacer par « avait ». Si le remplacement convient, j’écris « a », le verbe avoir. Sinon, la préposition peut s’écrire « à ».')]);
chapter('francais', 'Le présent et le futur', ['Le présent sert notamment à parler de maintenant ou d’une habitude.', 'Le futur simple situe une action après le moment où l’on parle.', 'Au futur : -ai, -as, -a, -ons, -ez, -ont.'], [MC('Complète au présent : « Nous … un livre. »', 'lisons', ['lirons', 'lisez', 'lisent'], 'Au présent, avec nous, le verbe lire s’écrit « lisons ».'), MC('Complète au présent : « Vous … attention. »', 'faites', ['faisez', 'font', 'ferez'], 'Le verbe faire se conjugue « vous faites » au présent.'), MC('Complète au futur : « Demain, tu … à la mare. »', 'iras', ['vas', 'allais', 'es allé'], 'Le futur simple du verbe aller à la deuxième personne est « tu iras ».'), PAIR('Relie le sujet à la forme du futur.', ['Je', 'Nous', 'Ils'], ['viendrai', 'viendrons', 'viendront'], 'Le futur de venir utilise le radical viendr- et les terminaisons du futur.'), SORT('Classe selon le temps du verbe.', ['Je prends le train.', 'Nous partirons demain.', 'Ils voient un héron.', 'Tu seras là.'], ['Présent', 'Futur simple'], [0, 1, 0, 1], 'Prends et voient sont au présent ; partirons et seras sont au futur.'), TF('« Elles auront » est le futur du verbe avoir.', true, 'Au futur simple, on dit : j’aurai, tu auras, elle aura, nous aurons, vous aurez, elles auront.'), MC('Complète : « Vous … un abri demain. »', 'construirez', ['construiront', 'construisez hier', 'construis'], 'Avec vous au futur, construire donne « construirez ».'), FREE('Transforme au futur : « Nous sommes dans la forêt et nous voyons un renard. »', 'Nous serons dans la forêt et nous verrons un renard. Les formes irrégulières sont serons et verrons.')]);
chapter('francais', 'Imparfait et passé composé', ['L’imparfait décrit souvent une situation ou une habitude passée.', 'Le passé composé comporte un auxiliaire au présent et un participe passé.', 'À l’imparfait : -ais, -ais, -ait, -ions, -iez, -aient.'], [MC('Complète à l’imparfait : « Autrefois, nous … près du bois. »', 'habitions', ['habitons', 'habiterons', 'avons habité'], 'Avec nous, l’imparfait porte la terminaison -ions.'), MC('Quelle forme est au passé composé ?', 'J’ai observé', ['J’observe', 'J’observais', 'J’observerai'], '« Ai » est l’auxiliaire avoir au présent, suivi du participe passé « observé ».'), MC('Complète au passé composé : « Elles … à midi. »', 'sont parties', ['ont parties', 'sont parti', 'partaient demain'], 'Partir se construit ici avec être ; « parties » s’accorde avec elles.'), PAIR('Relie les formes à leur construction.', ['Nous chantions', 'Ils ont chanté', 'Elle est venue'], ['Imparfait', 'Passé composé avec avoir', 'Passé composé avec être'], 'Le passé composé est un temps composé de deux éléments.'), TF('« Tu finissais » est à l’imparfait.', true, 'Le radical finiss- et la terminaison -ais forment l’imparfait.'), MC('Complète : « Hier, j’… mon dessin. »', 'ai fini', ['a fini', 'est fini', 'avais finir'], 'Avec je au passé composé : j’ai + fini.'), SORT('Classe les verbes selon leur temps.', ['il marchait', 'il a marché', 'nous étions', 'nous avons été'], ['Imparfait', 'Passé composé'], [0, 1, 0, 1], 'L’imparfait est une forme simple ; le passé composé utilise un auxiliaire.'), FREE('Écris une phrase avec une description à l’imparfait et une action au passé composé.', 'Il faisait froid quand le renard a traversé le sentier. « Faisait » décrit la situation ; « a traversé » raconte l’action.')]);
chapter('francais', 'Les temps du récit et l’impératif', ['Le passé simple se rencontre surtout dans les récits écrits.', 'Il est souvent associé à l’imparfait pour raconter des actions et décrire.', 'L’impératif exprime notamment une consigne, un conseil ou une demande, sans sujet exprimé.'], [MC('Dans « Le renard aperçut la mare », à quel temps est « aperçut » ?', 'Au passé simple', ['Au présent', 'Au futur', 'Au passé composé'], '« Aperçut » est une forme du passé simple d’apercevoir.'), MC('Complète au passé simple : « Les explorateurs … la porte. »', 'ouvrirent', ['ouvraient demain', 'ont ouvrir', 'ouvrent hier'], 'Avec ils, le passé simple d’ouvrir est « ouvrirent ».'), MC('Complète au passé simple : « Elle … une carte. »', 'trouva', ['trouvera', 'trouve', 'a trouver'], 'La troisième personne du passé simple de trouver est « trouva ».'), MC('Quelle phrase est à l’impératif ?', 'Observe les empreintes.', ['Tu observes les empreintes.', 'Il observe les empreintes.', 'Nous observerons les empreintes.'], 'Le verbe exprime une consigne et n’a pas de sujet exprimé.'), PAIR('Associe les formes à l’infinitif.', ['il fut', 'il eut', 'il fit'], ['être', 'avoir', 'faire'], 'Ce sont des formes fréquentes du passé simple dans les récits.'), TF('Dans « La nuit tombait quand un bruit retentit », « tombait » est à l’imparfait et « retentit » au passé simple.', true, 'L’imparfait décrit le cadre ; le passé simple raconte l’événement qui survient.'), MC('Quel conseil est correctement écrit à l’impératif ?', 'Prends ta gourde.', ['Tu prends ta gourde.', 'Prend ta gourde.', 'Prendre ta gourde hier.'], 'À la deuxième personne, l’impératif de prendre est « prends ».'), FREE('Écris deux phrases de récit, l’une à l’imparfait et l’autre au passé simple.', 'La forêt était silencieuse. Soudain, une chouette poussa un cri. Le cadre est à l’imparfait et l’action au passé simple.')]);
chapter('francais', 'Vocabulaire, familles et dictionnaire', ['Des mots d’une même famille ont un sens commun et souvent un radical commun.', 'Un préfixe se place avant le radical ; un suffixe après.', 'Le dictionnaire donne plusieurs sens : choisis celui qui correspond au contexte.'], [MC('Quel mot appartient à la famille de « terre » ?', 'terrestre', ['terrible', 'tendre', 'thermomètre'], 'Terre et terrestre partagent un radical et une relation de sens.'), MC('Quel est le contraire de « possible » ?', 'impossible', ['possiblement', 'possibilité', 'position'], 'Le préfixe im- marque ici le contraire.'), MC('Quel mot est un synonyme de « rapide » dans « un déplacement rapide » ?', 'vite effectué', ['immobile', 'très lent', 'silencieux obligatoirement'], 'Deux synonymes ont un sens proche dans un contexte donné.'), ORDER('Range ces mots dans l’ordre alphabétique.', ['arbre', 'branche', 'buisson', 'feuille'], 'Compare les lettres de gauche à droite. Branche vient avant buisson car r vient avant u.'), PAIR('Associe l’expression à son sens.', ['Un pied de table', 'Une feuille de papier', 'La bouche d’un fleuve'], ['Une partie qui soutient la table', 'Un support pour écrire', 'L’endroit où le fleuve rejoint la mer'], 'Un mot peut avoir plusieurs sens selon le contexte.'), MC('Dans « Le vent murmure », le mot « murmure » est employé…', 'au sens figuré', ['pour dire que le vent est humain', 'comme une date', 'comme un nombre'], 'On attribue au vent une action humaine pour créer une image.'), SORT('Classe ces mots selon leur construction.', ['rejouer', 'fillette', 'défaire', 'jardinier'], ['Avec un préfixe', 'Avec un suffixe'], [0, 1, 0, 1], 'Re- et dé- sont des préfixes. -ette et -ier sont des suffixes dans ces mots.'), FREE('Donne deux mots du champ lexical de la mer et utilise-les dans une phrase.', 'Par exemple : vague et bateau. « Une vague a soulevé le petit bateau. » Un champ lexical regroupe des mots liés à un même thème.')]);
chapter('francais', 'Littérature, poésie et points de vue', ['Le conte, le roman, la fable, le théâtre et la poésie proposent différentes façons de raconter et de créer.', 'Le narrateur est la voix qui raconte ; il ne faut pas le confondre avec l’auteur.', 'Une interprétation littéraire se discute en s’appuyant sur le texte.'], [MC('Dans « Je traversai le pont et découvris la clairière », le narrateur…', 'raconte à la première personne', ['ne peut pas être un personnage', 'est forcément l’auteur réel', 'raconte sans aucun point de vue'], 'Les pronoms je et les verbes à la première personne indiquent la voix du narrateur.'), MC('Quel élément appartient souvent au merveilleux d’un conte ?', 'Un animal qui parle comme un humain', ['Un trajet en autobus ordinaire', 'Une liste de courses', 'Un horaire de musée'], 'Le merveilleux fait accepter des événements impossibles dans le monde réel.'), MC('Au théâtre, une didascalie sert à…', 'indiquer notamment un geste ou une manière de jouer', ['toujours donner une réplique à dire', 'calculer un prix', 'définir une syllabe'], 'Les didascalies guident la mise en scène et ne sont généralement pas prononcées par les personnages.'), PAIR('Associe chaque forme à son indice fréquent.', ['Fable', 'Théâtre', 'Poème'], ['Un récit qui invite à réfléchir à une morale', 'Des répliques attribuées aux personnages', 'Un travail sur les sons, les images ou les rythmes'], 'Ces indices orientent la lecture sans enfermer toutes les œuvres dans une seule forme.'), TF('Un héros de récit peut avoir peur et commettre des erreurs.', true, 'Un personnage n’a pas besoin d’être parfait. Ses choix et son évolution construisent le récit.'), MC('« Le matin peint les toits d’or. » Quelle image est utilisée ?', 'Le matin est présenté comme un peintre.', ['Les toits deviennent réellement de l’or.', 'Il s’agit d’un calcul.', 'Aucune image n’est possible.'], 'Cette personnification rend la lumière du matin plus expressive.'), MC('Petit texte : « Lina partagea sa seule pomme avec son ami. Le lendemain, il l’aida à réparer son vélo. » Quel thème apparaît ?', 'L’entraide', ['La compétition sportive', 'La météo', 'Le commerce maritime'], 'Les deux actions montrent une aide réciproque.'), FREE('Écris quatre vers sur un lieu imaginaire. Relis-les à voix haute.', 'Mon poème propose un lieu imaginaire, des images précises et un rythme choisi. Les rimes sont possibles mais ne sont pas obligatoires.', {
  practice: true
})]);
chapter('francais', 'Écrire, relire et améliorer', ['Avant d’écrire, identifie le destinataire, le but et les idées importantes.', 'Organise un récit en étapes et utilise des reprises pour éviter les répétitions.', 'Relis séparément le sens, la ponctuation, les accords et les mots difficiles.'], [ORDER('Organise les grandes étapes d’une production écrite.', ['Chercher et organiser ses idées', 'Rédiger une première version', 'Relire le sens et la cohérence', 'Corriger puis préparer la version finale'], 'L’écriture progresse par essais, relectures et améliorations.'), MC('Pour écrire une lettre à la mairie demandant une piste cyclable, quel élément est le plus utile ?', 'Une demande claire et des raisons précises', ['Des insultes', 'Une liste sans rapport', 'Aucune formule d’adresse'], 'Le texte doit permettre au destinataire de comprendre la demande et ses raisons.'), MC('Quelle reprise évite une répétition ? « Léa ouvre son sac. … sort sa gourde. »', 'Elle', ['Ils', 'Tu', 'Nous'], '« Elle » reprend Léa et garde la cohérence du texte.'), MC('Quel connecteur convient à la dernière étape d’un récit ?', 'Enfin', ['D’abord', 'Parce que seulement', 'Autrefois toujours'], '« Enfin » peut annoncer la dernière étape.'), TF('Relire son texte peut conduire à déplacer ou supprimer une phrase.', true, 'Réviser un texte ne consiste pas seulement à corriger l’orthographe : on peut aussi améliorer l’organisation et la précision.'), PAIR('Relie le type d’écrit à son objectif.', ['Récit', 'Description', 'Texte explicatif'], ['Raconter des événements', 'Faire imaginer un être ou un lieu', 'Faire comprendre un fonctionnement'], 'L’objectif guide les informations et l’organisation de l’écrit.'), FREE('Écris un récit de six à dix phrases : Nox découvre une porte mystérieuse dans la forêt.', 'Mon récit présente le lieu et le personnage, un événement, les actions de Nox et une fin. Les temps sont cohérents, les phrases ponctuées et les accords relus.', {
  practice: true
}), FREE('Relis un de tes textes. Choisis deux améliorations et explique-les.', 'Je peux ajouter un détail pour mieux comprendre le lieu et remplacer une répétition par un pronom. Je vérifie ensuite que les nouvelles phrases restent claires.', {
  practice: true
})]);
chapter('francais', 'Parler, écouter et argumenter', ['Pour être compris, organise tes idées et adapte le volume de ta voix.', 'Écouter, c’est aussi reformuler et poser une question utile.', 'Un avis devient un argument quand on donne une raison et un exemple.'], [MC('Pendant un exposé, que vaut-il mieux faire ?', 'Regarder parfois son public et parler distinctement', ['Lire très vite sans pause', 'Parler en tournant le dos', 'Crier tout le temps'], 'Le regard, l’articulation et les pauses aident l’auditoire à comprendre.'), MC('Quel énoncé contient un argument ?', 'Je préfère le vélo pour ce trajet car il ne produit pas de gaz d’échappement en roulant.', ['Le vélo, voilà.', 'C’est comme ça.', 'Je refuse d’expliquer.'], 'La phrase donne une préférence puis une raison précise.'), ORDER('Prépare un court exposé.', ['Choisir la question à présenter', 'Chercher et vérifier les informations', 'Organiser un début, un développement et une fin', 'S’entraîner à voix haute'], 'Une préparation structurée rend l’exposé plus clair.'), TF('On peut ne pas être d’accord tout en respectant son interlocuteur.', true, 'On discute les idées sans attaquer la personne.'), MC('Après avoir écouté un camarade, quelle phrase aide à vérifier sa compréhension ?', 'Si je comprends bien, tu veux dire que…', ['Tu as tort avant même de parler.', 'Je n’ai pas écouté.', 'Je change de sujet.'], 'Reformuler permet de vérifier le sens et d’éviter les malentendus.'), PAIR('Associe le geste oral à son but.', ['Faire une pause', 'Donner un exemple', 'Annoncer son plan'], ['Laisser le temps de comprendre', 'Rendre une idée concrète', 'Aider à suivre l’organisation'], 'La prise de parole se construit pour aider ceux qui écoutent.'), FREE('Présente oralement un livre en une minute environ, sans chronomètre imposé.', 'Je donne le titre, présente les personnages et le début sans tout raconter, puis explique ce qui m’a intéressé. Je parle assez clairement et je regarde mon auditoire.', {
  practice: true
}), FREE('Avec un adulte ou un camarade, discute : faut-il garder un coin de cour sauvage ? Donne deux arguments et écoute une objection.', 'Je peux parler d’abris pour les animaux et de découvertes scientifiques. J’écoute l’objection sur l’usage de la cour et propose un espace délimité. Les arguments peuvent varier.', {
  practice: true
})]);

// HISTOIRE — les trois thèmes annuels du CM2, avec repères et lecture de sources.
chapter('histoire', 'La République et ses symboles', ['La Première République est proclamée en 1792 ; la France a ensuite connu plusieurs régimes.', 'La République s’appuie sur des institutions, des libertés et l’égalité devant la loi.', 'Drapeau tricolore, Marianne, devise et hymne sont des symboles républicains.'], [MC('En quelle année la Première République est-elle proclamée en France ?', '1792', ['1492', '1918', '2002'], 'La Première République est proclamée en septembre 1792.'), MC('Pourquoi fête-t-on le centenaire de la République en 1892 ?', 'Cent ans se sont écoulés depuis 1792.', ['La France a toujours été une République.', 'La Première Guerre mondiale vient de finir.', 'L’euro vient d’être créé.'], '1892 − 1792 = 100 ans. La France a toutefois connu d’autres régimes entre ces dates.'), PAIR('Associe les symboles.', ['Marianne', 'La Marseillaise', 'Liberté, Égalité, Fraternité'], ['Figure de la République', 'Hymne national français', 'Devise de la République'], 'Ces symboles sont notamment visibles dans les lieux publics et les cérémonies.'), ORDER('Classe ces repères du plus ancien au plus récent.', ['1789 : Révolution française', '1792 : Première République', '1848 : Deuxième République', '1870 : Troisième République'], 'La chronologie permet de voir que la République s’est construite au fil de changements politiques.'), TF('La France a été une République sans interruption depuis 1792.', false, 'Il y a notamment eu des Empires et des monarchies après 1792.'), FREE('Que peut apprendre un historien en observant une affiche de la fête républicaine de 1892 ?', 'Il peut étudier la manière dont on célèbre la République, ses symboles et le message de l’affiche. Il regarde sa date, son auteur et son destinataire avant de l’interpréter.')]);
chapter('histoire', 'L’école et la conquête des droits', ['Les lois de 1881 et 1882 rendent l’école publique gratuite et l’instruction obligatoire ; l’école publique devient laïque.', 'Des droits se sont élargis progressivement, après des débats et des luttes.', 'Il faut comparer les situations d’hier et d’aujourd’hui sans supposer qu’elles étaient identiques.'], [MC('Quel changement est associé à la loi scolaire de 1881 ?', 'La gratuité de l’enseignement primaire public', ['L’apparition d’Internet', 'La création de l’euro', 'La suppression de tous les livres'], 'La loi de 1881 établit la gratuité de l’enseignement primaire public.'), MC('Que signifie « école publique laïque » ?', 'L’enseignement public est indépendant des religions.', ['Les élèves doivent tous avoir la même croyance.', 'Les sciences y sont interdites.', 'Les enfants n’ont aucun droit.'], 'La laïcité de l’école publique protège la liberté de conscience et la neutralité de l’enseignement.'), PAIR('Relie chaque date au repère historique.', ['1848', '1882', '1944'], ['Abolition de l’esclavage dans les colonies françaises', 'Instruction obligatoire et laïcisation de l’école publique', 'Droit de vote accordé aux femmes en France'], 'Ces repères montrent une construction progressive des droits.'), TF('Au XIXe siècle, toutes les femmes françaises disposaient déjà du droit de vote.', false, 'Le droit de vote est accordé aux femmes en France en 1944 ; elles votent pour la première fois en 1945.'), MC('Quel document aide à étudier une ancienne salle de classe ?', 'Une photographie datée de cette classe', ['Une rumeur sans source', 'Une publicité de téléphone actuelle', 'Un calcul sans rapport'], 'La photographie est une source qu’il faut dater, situer et examiner.'), FREE('Compare une école d’autrefois à ton école. Donne une différence et un point commun possibles.', 'On peut comparer les outils, les vêtements, l’organisation ou les contenus. Par exemple : autrefois on utilisait souvent une ardoise ; aujourd’hui aussi on apprend à lire, écrire et compter. Il faut vérifier avec des documents.')]);
chapter('histoire', 'Machines, usines et transports', ['Au XIXe siècle, l’industrialisation transforme la production, les transports et les paysages.', 'La machine à vapeur utilise l’énergie de la vapeur et permet de faire fonctionner des machines.', 'Le chemin de fer facilite le transport des personnes et des marchandises.'], [MC('Quel changement caractérise l’industrialisation ?', 'Le développement des machines et des usines', ['La disparition de tous les échanges', 'L’invention de l’agriculture préhistorique', 'L’abandon de tous les transports'], 'L’industrialisation augmente la production et transforme le travail.'), MC('Quelle ressource alimente de nombreuses machines à vapeur industrielles au XIXe siècle ?', 'Le charbon', ['Une batterie de téléphone', 'L’énergie solaire photovoltaïque', 'Le plastique recyclé'], 'Le charbon est brûlé pour chauffer l’eau et produire de la vapeur.'), PAIR('Associe le lieu à son activité.', ['Mine', 'Usine textile', 'Gare'], ['Extraire du charbon', 'Produire des tissus avec des machines', 'Accueillir les trains et les voyageurs'], 'Ces lieux appartiennent aux nouveaux paysages industriels.'), ORDER('Organise le fonctionnement simplifié d’une machine à vapeur.', ['Brûler du combustible', 'Chauffer de l’eau', 'Produire de la vapeur', 'Mettre un mécanisme en mouvement'], 'La chaleur permet de produire la vapeur qui actionne un mécanisme.'), TF('Le chemin de fer a contribué à accélérer les déplacements au XIXe siècle.', true, 'Les trains permettent de transporter des voyageurs et de lourdes marchandises sur de longues distances.'), FREE('Observe mentalement un paysage avec mine, usine et voie ferrée. Explique un lien entre ces éléments.', 'La mine fournit du charbon, l’usine l’utilise comme source d’énergie et le train transporte charbon, produits et voyageurs.')]);
chapter('histoire', 'Travailler et vivre au XIXe siècle', ['Les ouvriers, les artisans, les commerçants et les paysans n’ont pas les mêmes conditions de travail.', 'L’essor industriel s’accompagne de villes qui grandissent et de migrations depuis les campagnes.', 'Les conditions de travail et les droits des travailleurs évoluent progressivement.'], [MC('Qu’appelle-t-on l’exode rural ?', 'Le départ d’habitants des campagnes vers les villes', ['Le voyage de tous les citadins vers la mer', 'La disparition des villages en un jour', 'Un trajet quotidien en train uniquement'], 'De nombreux habitants quittent la campagne pour chercher du travail en ville.'), MC('Dans une usine du XIXe siècle, un ouvrier…', 'travaille souvent de longues journées pour un salaire', ['possède obligatoirement toute l’usine', 'ne suit aucune règle', 'utilise forcément un ordinateur'], 'Les conditions de travail sont souvent difficiles et les protections se développent peu à peu.'), SORT('Associe ces activités au milieu principal décrit.', ['Cultiver le blé', 'Travailler dans une grande usine', 'Élever des vaches dans une ferme', 'Vendre dans un grand magasin urbain'], ['Campagne', 'Ville industrielle'], [0, 1, 0, 1], 'Les activités agricoles restent importantes tandis que l’industrie et le commerce urbain se développent.'), TF('Des enfants travaillaient dans certaines mines et usines au XIXe siècle.', true, 'Le travail des enfants existait ; des lois l’ont progressivement limité et l’instruction obligatoire a contribué à le réduire.'), MC('Pour comprendre le travail ouvrier, quelle comparaison est la plus utile ?', 'Croiser un témoignage, une photographie et un règlement d’usine', ['Lire une seule publicité sans date', 'Inventer une réponse sans document', 'Regarder seulement la couleur d’un bâtiment'], 'Plusieurs sources apportent des points de vue et des informations complémentaires.'), FREE('Pourquoi l’industrialisation ne transforme-t-elle pas seulement les machines ?', 'Elle modifie les métiers, les conditions de travail, la taille des villes, les transports et la vie quotidienne des familles.')]);
chapter('histoire', 'La Première Guerre mondiale', ['La Première Guerre mondiale se déroule de 1914 à 1918.', 'Les soldats combattent notamment dans les tranchées ; les civils sont aussi touchés par la guerre.', 'L’armistice du 11 novembre 1918 met fin aux combats sur le front occidental.'], [MC('Quelles dates encadrent la Première Guerre mondiale ?', '1914–1918', ['1939–1945', '1789–1792', '1957–1992'], 'La Première Guerre mondiale commence en 1914 et se termine en 1918.'), MC('Qu’est-ce qu’une tranchée de cette guerre ?', 'Un fossé aménagé pour protéger les combattants', ['Une usine textile', 'Un type de train', 'Un traité de paix'], 'Les tranchées sont des positions creusées dans le sol.'), MC('Quel repère est associé à Verdun ?', 'Une grande bataille de 1916', ['La création de la République en 1792', 'Le début de l’euro', 'La fin de la Seconde Guerre mondiale'], 'La bataille de Verdun est un repère majeur de la Première Guerre mondiale.'), TF('La Première Guerre mondiale ne concerne que les soldats et ne touche pas les civils.', false, 'Les civils connaissent aussi les deuils, les destructions, les pénuries et la mobilisation du travail.'), ORDER('Remets les repères dans l’ordre.', ['1914 : début de la guerre', '1916 : bataille de Verdun', '11 novembre 1918 : armistice', '1919 : traité de Versailles'], 'Un armistice arrête les combats ; un traité organise ensuite la paix.'), FREE('Pourquoi conserve-t-on des monuments aux morts ?', 'Ils rendent hommage aux personnes mortes à la guerre et permettent de transmettre la mémoire des conflits. Les inscriptions constituent aussi des sources pour l’histoire locale.')]);
chapter('histoire', 'La Seconde Guerre mondiale et les résistances', ['La Seconde Guerre mondiale se déroule de 1939 à 1945.', 'La France connaît la défaite, l’Occupation, la collaboration et différentes formes de Résistance.', 'Le régime nazi organise des persécutions et des génocides, notamment celui des Juifs d’Europe, appelé la Shoah.'], [MC('Quelles dates encadrent la Seconde Guerre mondiale ?', '1939–1945', ['1914–1918', '1881–1882', '1792–1804'], 'La guerre commence en 1939 et se termine en 1945.'), MC('Que désigne la Résistance en France pendant l’Occupation ?', 'Des actions contre l’occupation nazie et ses soutiens', ['Le nom d’un nouvel impôt', 'Un simple sport', 'Une compagnie de trains'], 'La Résistance prend des formes diverses : informer, cacher des personnes persécutées, transmettre des renseignements ou combattre.'), MC('Quel événement est lié au 18 juin 1940 ?', 'L’appel du général de Gaulle à poursuivre le combat', ['L’armistice de 1918', 'La création de la Première République', 'La signature du traité de Rome'], 'Depuis Londres, de Gaulle appelle à poursuivre le combat.'), TF('Les persécutions nazies reposaient sur des idées racistes et antisémites.', true, 'Le régime nazi a persécuté et assassiné des populations désignées par son idéologie, notamment les Juifs d’Europe.'), ORDER('Replace les repères de la guerre en Europe.', ['1939 : début de la guerre', '1940 : défaite française et appel du 18 juin', '1944 : débarquement en Normandie', '8 mai 1945 : fin de la guerre en Europe'], 'Le 8 mai 1945 marque la fin de la guerre en Europe, et non encore dans tout le monde.'), FREE('Explique pourquoi apprendre l’histoire de la Shoah est important.', 'Cela permet de connaître les persécutions et le génocide des Juifs d’Europe, de respecter la mémoire des victimes et de comprendre les dangers du racisme et de l’antisémitisme.')]);
chapter('histoire', 'Construire la paix en Europe', ['Après les guerres, des pays européens développent une coopération pour favoriser la paix.', 'Le traité de Rome est signé en 1957 ; le traité de Maastricht en 1992.', 'L’Union européenne est une organisation de pays : elle ne se confond pas avec tout le continent européen.'], [MC('Quel objectif important guide la construction européenne après 1945 ?', 'Favoriser une paix durable par la coopération', ['Préparer une nouvelle guerre entre voisins', 'Interdire tous les voyages', 'Supprimer les échanges culturels'], 'La coopération économique et politique cherche à rapprocher les anciens adversaires.'), MC('En quelle année les traités de Rome sont-ils signés ?', '1957', ['1914', '1792', '2002'], 'Les traités de Rome de 1957 sont un repère de la construction européenne.'), MC('Le traité de Maastricht, signé en 1992, est associé à…', 'la création de l’Union européenne', ['la Première République', 'la bataille de Verdun', 'l’invention de l’imprimerie'], 'Le traité est signé en 1992 et entre en vigueur en 1993.'), PAIR('Associe le symbole ou l’outil à son rôle.', ['Drapeau européen', 'Euro', 'Parlement européen'], ['Un cercle de douze étoiles', 'Monnaie partagée par une partie des pays de l’Union', 'Institution où siègent des représentants élus'], 'Tous les pays européens n’utilisent pas l’euro et tous ne font pas partie de l’Union.'), TF('L’Europe et l’Union européenne désignent exactement la même chose.', false, 'L’Europe est un ensemble géographique. L’Union européenne réunit une partie de ses pays dans une organisation politique et économique.'), FREE('Explique une différence entre faire la guerre et coopérer entre pays.', 'Coopérer consiste à chercher des accords et à mener des projets communs par la discussion et des règles partagées, plutôt que par la violence armée.')]);

// GÉOGRAPHIE — se déplacer, communiquer, mieux habiter et outils du géographe.
chapter('geographie', 'Cartes, paysages et échelles', ['Une carte représente un espace avec des symboles expliqués par une légende.', 'L’orientation et l’échelle aident à se repérer et à estimer les distances.', 'Un paysage se décrit et s’explique : habitat, activités, voies de transport et éléments naturels.'], [MC('Sur une carte, à quoi sert la légende ?', 'À expliquer les symboles et couleurs', ['À donner toujours la météo', 'À remplacer tous les noms', 'À mesurer une masse'], 'La légende est la clé de lecture des symboles.'), MC('Une flèche indique le nord vers le haut de la carte. Où est l’est ?', 'À droite', ['À gauche', 'En bas', 'Au centre obligatoirement'], 'Quand le nord est en haut, l’est se trouve à droite.'), PAIR('Relie l’échelle d’étude à l’espace.', ['Locale', 'Nationale', 'Mondiale'], ['Un quartier', 'L’ensemble de la France', 'L’ensemble du globe'], 'Changer d’échelle permet de voir des phénomènes différents.'), TF('La France comprend aussi des territoires situés hors d’Europe.', true, 'Les territoires ultramarins se trouvent dans plusieurs régions du monde.'), NUM('Sur un plan, 1 cm représente 500 m. Que représentent 3 cm en mètres ?', 1500, '3 × 500 = 1 500 m.', 'm'), FREE('Décris ton trajet entre chez toi et l’école sans indiquer ton adresse précise.', 'Je peux décrire les modes de déplacement, les types de voies, un passage piéton et les paysages traversés. Je ne publie pas mes informations personnelles.', {
  practice: true
})]);
chapter('geographie', 'Se déplacer au quotidien', ['Les déplacements répondent à des besoins : école, travail, achats, loisirs.', 'Le mode de déplacement dépend des distances, des équipements et des besoins des personnes.', 'Marcher, pédaler et utiliser des transports collectifs peuvent limiter certaines pollutions.'], [MC('Quel exemple est un déplacement quotidien ?', 'Aller à l’école', ['Rester assis dans sa chambre', 'Lire un livre immobile', 'Dormir'], 'Un trajet régulier vers l’école fait partie des mobilités du quotidien.'), MC('Pourquoi une personne en zone rurale peut-elle dépendre davantage de la voiture ?', 'Les distances peuvent être longues et les transports collectifs moins fréquents.', ['Les voitures y sont obligatoires pour tous.', 'Personne ne peut y marcher.', 'Les villages n’ont aucune route.'], 'La densité de population et les équipements influencent les possibilités de déplacement.'), SORT('Classe ces modes.', ['Marcher', 'Tramway', 'Vélo', 'Métro'], ['Mobilité active', 'Transport collectif'], [0, 1, 0, 1], 'La marche et le vélo utilisent principalement l’activité physique ; tramway et métro transportent plusieurs voyageurs.'), TF('Une piste cyclable et un trottoir accessible peuvent faciliter les déplacements.', true, 'Des aménagements adaptés rendent les trajets plus sûrs et plus accessibles.'), MC('Quel aménagement aide particulièrement une personne en fauteuil roulant ?', 'Un cheminement sans obstacle avec des accès adaptés', ['Un escalier sans autre accès', 'Un trottoir encombré', 'Une porte trop étroite'], 'L’accessibilité permet à chacun de circuler.'), FREE('Propose une amélioration pour les trajets près d’une école et explique son intérêt.', 'On peut proposer un passage piéton mieux placé, un trottoir dégagé ou un stationnement pour vélos. Il faut tenir compte de la sécurité et des besoins des usagers.')]);
chapter('geographie', 'Voyager en France et dans le monde', ['Les réseaux de transport relient des lieux à différentes distances.', 'Les gares, aéroports et ports sont des nœuds de ces réseaux.', 'Un voyage peut combiner plusieurs modes : c’est l’intermodalité.'], [MC('Quel lieu est un nœud du réseau ferroviaire ?', 'Une gare où plusieurs lignes se croisent', ['Un arbre isolé', 'Une plage sans accès', 'Une cour fermée sans voie'], 'Un nœud de transport est un point où se rencontrent des lignes ou des modes.'), PAIR('Relie le moyen de transport à l’infrastructure.', ['Train', 'Avion', 'Navire'], ['Voie ferrée et gare', 'Aéroport', 'Port'], 'Les déplacements nécessitent des infrastructures adaptées.'), MC('Bus puis train puis marche : ce trajet est…', 'intermodal', ['sans déplacement', 'uniquement maritime', 'forcément impossible'], 'Il combine plusieurs modes de transport.'), TF('Le moyen le plus rapide est toujours le moins polluant par voyageur.', false, 'La vitesse et les effets environnementaux sont deux critères différents, à comparer selon le trajet et le remplissage.'), MC('Avant un long voyage, quelles informations sont utiles ?', 'Les horaires, correspondances, durée et coût', ['Uniquement la couleur du billet', 'Le prénom de tous les passagers', 'La taille du conducteur'], 'Ces informations permettent de préparer un trajet adapté.'), FREE('Compare le train et l’avion pour un voyage entre deux grandes villes européennes.', 'Je compare les gares ou aéroports, les correspondances, le temps total, le prix, l’accessibilité et les effets sur l’environnement. La réponse dépend des lieux et du trajet.')]);
chapter('geographie', 'Des mobilités inégales', ['On ne se déplace pas partout de la même manière.', 'Les reliefs, les distances, le coût et les infrastructures créent des contraintes.', 'L’accès aux transports peut être inégal entre les territoires et les personnes.'], [MC('Dans une région montagneuse, quel élément peut compliquer un trajet ?', 'Le relief', ['La présence d’un cahier', 'Le nom d’un voyageur', 'Une affiche de cinéma seule'], 'Les pentes, les cols et les vallées influencent la construction et l’usage des voies.'), MC('Pourquoi construire une passerelle piétonne au-dessus d’une rivière ?', 'Pour relier des quartiers séparés par l’eau', ['Pour supprimer toutes les écoles', 'Pour remplacer les trains du monde', 'Pour arrêter la rotation de la Terre'], 'Un aménagement peut réduire un obstacle au déplacement.'), PAIR('Relie la difficulté à une réponse possible.', ['Trop peu de bus', 'Obstacle à franchir en fauteuil', 'Trajet très long à pied'], ['Améliorer la desserte collective', 'Créer une rampe ou un accès adapté', 'Prévoir une solution de transport adaptée'], 'Les réponses dépendent des besoins réels des habitants.'), TF('Tous les habitants du monde ont les mêmes possibilités de déplacement.', false, 'Les ressources, les infrastructures, la sécurité et les distances rendent les mobilités inégales.'), MC('Pour comparer deux trajets dans deux pays, que faut-il observer ?', 'Distance, durée, coût et moyens disponibles', ['Seulement le nom des pays', 'Uniquement la couleur des véhicules', 'Le hasard'], 'Une comparaison s’appuie sur plusieurs critères précis.'), FREE('Explique ce qu’est une inégalité d’accès aux transports avec un exemple.', 'Deux habitants n’ont pas les mêmes possibilités de rejoindre une école ou un service : par exemple, l’un dispose d’un bus fréquent et l’autre doit parcourir une grande distance sans transport collectif.')]);
chapter('geographie', 'Internet relie le monde', ['Internet est un réseau mondial qui relie des réseaux d’ordinateurs.', 'Il utilise des équipements matériels : câbles, antennes, routeurs et centres de données.', 'L’accès au réseau et ses usages sont inégaux selon les lieux et les personnes.'], [MC('Internet fonctionne notamment grâce à…', 'des câbles, antennes et équipements informatiques', ['une magie sans matériel', 'un seul ordinateur mondial', 'des feuilles de papier uniquement'], 'Les échanges numériques reposent sur des infrastructures bien réelles.'), MC('Que permettent des câbles sous-marins de télécommunication ?', 'De transmettre des données entre des régions du monde', ['De faire circuler les trains', 'De remplacer les océans', 'De fabriquer du vent'], 'Des câbles transportent de grandes quantités de données entre les continents.'), TF('Tous les habitants du monde disposent du même accès à Internet.', false, 'L’accès varie selon les infrastructures, les coûts, les équipements et les compétences.'), PAIR('Relie l’outil ou le lieu à sa fonction.', ['Moteur de recherche', 'Centre de données', 'Messagerie'], ['Aider à trouver des pages', 'Héberger et traiter des données', 'Échanger des messages'], 'Les services numériques ont des fonctions différentes et utilisent des équipements.'), MC('Quel effet environnemental peut être lié au numérique ?', 'L’usage d’énergie et de ressources pour les équipements', ['Aucun effet matériel possible', 'La disparition de toute consommation électrique', 'La fabrication gratuite de matières premières'], 'Les appareils, les réseaux et le stockage nécessitent des matériaux et de l’énergie.'), FREE('Pourquoi dit-on qu’un message numérique voyage dans un réseau matériel ?', 'Il est transmis entre des appareils par des câbles ou des ondes, avec des antennes, routeurs et serveurs. Le numérique ne fonctionne pas sans équipements.')]);
chapter('geographie', 'Mieux habiter demain', ['Mieux habiter, c’est améliorer le cadre de vie en tenant compte de tous les habitants.', 'Espaces verts, eau, logements, transports et déchets sont des questions liées.', 'Un écoquartier cherche à limiter ses effets environnementaux et à répondre à des besoins sociaux.'], [MC('Quel projet peut contribuer à mieux habiter ?', 'Créer un parc accessible relié aux quartiers à pied', ['Supprimer tous les trottoirs', 'Polluer une rivière', 'Fermer tous les lieux publics'], 'Il peut améliorer le cadre de vie, les rencontres et les déplacements.'), SORT('Classe les aménagements.', ['Planter des arbres adaptés', 'Rejeter des déchets dans un cours d’eau', 'Installer des équipements pour trier', 'Bétonner tout un jardin sans autre espace'], ['Peut améliorer le milieu', 'Peut dégrader le milieu'], [0, 1, 0, 1], 'Les choix d’aménagement ont des effets sur l’eau, le vivant, les déplacements et les usages.'), MC('Quelle différence existe entre trier et recycler ?', 'Trier sépare les déchets ; recycler transforme certaines matières.', ['Les deux veulent dire brûler tous les déchets.', 'Recycler signifie seulement déplacer un sac.', 'Trier fabrique toujours un objet neuf.'], 'Le tri facilite la collecte par matière ; le recyclage intervient ensuite quand il est possible.'), TF('Pour concevoir un quartier, il faut écouter les besoins de plusieurs types d’habitants.', true, 'Enfants, personnes âgées, personnes handicapées, travailleurs et autres habitants ont des besoins à prendre en compte.'), PAIR('Relie le besoin à l’aménagement.', ['Se rafraîchir et se rencontrer', 'Se déplacer à vélo', 'Réduire certains déchets'], ['Des espaces verts et ombragés', 'Des itinéraires cyclables adaptés', 'Des possibilités de réparation et de réemploi'], 'Mieux habiter combine plusieurs objectifs.'), FREE('Dessine sur papier ton quartier de demain avec trois aménagements utiles.', 'J’indique des logements, des cheminements accessibles, des espaces de rencontre ou de nature. J’explique au moins trois choix et les personnes qui en bénéficient.', {
  practice: true
})]);

// SCIENCES ET TECHNOLOGIE — complément aux 60 questions biodiversité conservées.
chapter('sciences', 'Matière et changements d’état', ['Une même matière peut exister à l’état solide, liquide ou gazeux.', 'La fusion transforme un solide en liquide ; la solidification fait l’inverse.', 'La vapeur d’eau est un gaz invisible ; les petites gouttes d’un nuage sont liquides.'], [PAIR('Associe chaque exemple à son état.', ['Un glaçon', 'L’eau d’un verre', 'La vapeur d’eau invisible'], ['Solide', 'Liquide', 'Gazeux'], 'L’eau peut se présenter sous trois états selon les conditions.'), MC('Comment s’appelle le passage de la glace à l’eau liquide ?', 'La fusion', ['La solidification', 'La condensation liquide', 'La filtration'], 'Lors de la fusion, un solide devient liquide.'), MC('Le linge mouillé sèche sans que l’eau bout. Quel changement intervient ?', 'L’évaporation', ['La congélation', 'La fusion', 'La sédimentation'], 'L’évaporation fait passer de l’eau liquide à l’état gazeux à sa surface.'), TF('L’air est de la matière, même s’il est invisible.', true, 'L’air occupe un volume et possède une masse. Un ballon gonflé contient de l’air.'), SORT('Classe ces changements.', ['Glace qui fond', 'Eau qui gèle', 'Buée qui se forme sur une vitre froide', 'Eau qui s’évapore'], ['Solide → liquide', 'Liquide → solide', 'Gaz → liquide', 'Liquide → gaz'], [0, 1, 2, 3], 'Chaque changement d’état a un sens précis.'), FREE('Comment montrer que de l’air occupe une place sans le voir ?', 'On peut gonfler un ballon ou tenter d’enfoncer un verre retourné dans l’eau : l’air emprisonné empêche l’eau de remplir immédiatement tout le verre. Je réalise les manipulations avec du matériel adapté.', {
  practice: true
})]);
chapter('sciences', 'Mélanges et séparation', ['Un mélange contient plusieurs constituants. Certains sont visibles, d’autres non.', 'Dissoudre du sel dans l’eau ne le fait pas disparaître.', 'Filtration, décantation et évaporation servent à des séparations différentes.'], [MC('Quel mélange est homogène à l’œil nu après agitation suffisante ?', 'Un peu de sel entièrement dissous dans de l’eau', ['Du sable dans de l’eau', 'Des cailloux et des feuilles', 'De l’eau et de l’huile séparées'], 'On ne distingue pas les constituants du mélange eau-sel à l’œil nu.'), MC('Comment retirer du sable non dissous dans de l’eau ?', 'Par filtration', ['En ajoutant du sucre', 'En le renommant', 'Avec une boussole'], 'Le filtre retient les particules de sable et laisse passer l’eau.'), TF('Le sel dissous dans l’eau n’existe plus.', false, 'Le sel reste dans le mélange même s’il n’est plus visible. On peut le retrouver en laissant évaporer l’eau.'), PAIR('Relie le mélange à la méthode proposée.', ['Eau et sable', 'Eau et sel dissous', 'Eau boueuse laissée au repos'], ['Filtration', 'Évaporation de l’eau pour récupérer le sel', 'Décantation'], 'Une méthode se choisit selon les propriétés des constituants.'), MC('L’eau et l’huile au repos…', 'forment généralement deux couches', ['forment toujours une seule matière pure', 'deviennent du sable', 'sont impossibles à observer'], 'L’huile et l’eau ne se mélangent pas durablement dans ces conditions.'), FREE('Propose une expérience pour comparer la dissolution du sucre et du sable dans l’eau.', 'Je prends deux récipients avec la même quantité d’eau, j’ajoute séparément un peu de sucre et de sable, puis je mélange de la même façon. J’observe : le sucre peut se dissoudre, le sable non.', {
  practice: true
})]);
chapter('sciences', 'Énergies et transformations', ['On utilise de l’énergie pour se chauffer, éclairer et mettre en mouvement.', 'Le Soleil, le vent et les combustibles sont des sources d’énergie de natures différentes.', 'Une énergie peut être transformée : un moteur électrique transforme notamment de l’énergie électrique en mouvement et en chaleur.'], [MC('Quelle est la source d’énergie principale d’un panneau photovoltaïque ?', 'La lumière du Soleil', ['Le bruit', 'Le charbon placé dessus', 'Le sel'], 'Le panneau photovoltaïque transforme une partie de l’énergie lumineuse reçue en énergie électrique.'), SORT('Classe les sources à l’échelle humaine.', ['Vent', 'Charbon', 'Lumière solaire', 'Pétrole'], ['Renouvelable', 'Non renouvelable'], [0, 1, 0, 1], 'Le vent et le rayonnement solaire se renouvellent ; les stocks de charbon et de pétrole se forment très lentement.'), MC('Une éolienne utilise principalement…', 'le mouvement de l’air', ['la chaleur d’un volcan directement', 'le goût de l’eau', 'la couleur du ciel'], 'Le vent met les pales en mouvement, ce qui permet de produire de l’électricité.'), TF('L’électricité peut être produite à partir de différentes sources d’énergie.', true, 'On peut notamment utiliser le vent, l’eau en mouvement, le rayonnement solaire ou la chaleur de certains combustibles.'), PAIR('Associe l’objet à son effet principal recherché.', ['Lampe', 'Radiateur', 'Ventilateur'], ['Éclairer', 'Chauffer', 'Mettre l’air en mouvement'], 'Ces objets convertissent de l’énergie pour répondre à un besoin.'), FREE('Propose deux moyens raisonnés d’éviter de gaspiller l’énergie à l’école.', 'On peut éteindre un éclairage inutile et fermer une fenêtre pendant qu’un chauffage fonctionne, selon les consignes d’aération de l’école. On distingue besoin réel et gaspillage.')]);
chapter('sciences', 'Électricité : un circuit qui fonctionne', ['Pour allumer une lampe avec une pile, le circuit doit former une boucle conductrice fermée.', 'Un interrupteur ouvre ou ferme le circuit.', 'Les expériences scolaires utilisent uniquement des piles adaptées, jamais une prise de courant.'], [MC('Pour qu’une lampe s’allume avec une pile, il faut…', 'une boucle fermée reliant les deux bornes de la pile à la lampe', ['un fil posé à côté de la pile', 'une boucle interrompue', 'brancher la lampe à une feuille sèche seulement'], 'Un circuit fermé permet la circulation du courant.'), MC('Que fait un interrupteur ouvert ?', 'Il interrompt la boucle du circuit.', ['Il fabrique une pile.', 'Il change un fil en bois.', 'Il allume toujours la lampe.'], 'L’ouverture de l’interrupteur coupe le passage du courant dans cette boucle.'), SORT('Classe les matériaux dans une expérience simple avec une pile.', ['Fil de cuivre', 'Plastique sec', 'Pièce métallique conductrice', 'Bois sec'], ['Conducteur', 'Isolant'], [0, 1, 0, 1], 'Les métaux cités conduisent le courant ; le plastique et le bois secs sont isolants dans cette situation.'), TF('On peut tester un montage scolaire en le branchant directement à une prise murale.', false, 'On utilise uniquement le matériel scolaire à piles adapté et les consignes de l’adulte. Une prise murale est dangereuse.'), MC('Une lampe ne s’allume pas. Quel contrôle est pertinent ?', 'Vérifier la pile, la lampe, les contacts et la fermeture du circuit', ['Toucher une prise avec un fil', 'Ajouter de l’eau sur le montage', 'Casser la lampe'], 'Il faut rechercher méthodiquement une cause avec du matériel adapté.'), FREE('Dessine un circuit simple avec une pile, une lampe et un interrupteur fermé.', 'Le dessin montre une boucle conductrice complète passant par la pile, la lampe et l’interrupteur. Les contacts sont reliés correctement. Aucun fil ne relie directement les bornes de la pile sans récepteur.', {
  practice: true
})]);
chapter('sciences', 'Mouvements et objets techniques', ['Un objet technique est conçu pour répondre à un besoin.', 'Un mouvement se décrit par rapport à un observateur, avec une trajectoire et une vitesse.', 'La fonction d’usage explique à quoi sert l’objet ; les solutions techniques expliquent comment il fonctionne.'], [MC('Quelle est la fonction d’usage principale d’un vélo ?', 'Permettre de se déplacer', ['Mesurer une température', 'Éclairer une pièce entière', 'Conserver des aliments au froid'], 'La fonction d’usage décrit le besoin auquel répond l’objet.'), MC('La trajectoire d’un point d’une nacelle de grande roue en mouvement est…', 'circulaire', ['toujours rectiligne', 'sans mouvement', 'un carré'], 'Le point suit un cercle autour de l’axe de la roue.'), PAIR('Relie l’élément du vélo à sa fonction technique.', ['Freins', 'Chaîne', 'Guidon'], ['Ralentir ou arrêter', 'Transmettre un mouvement', 'Diriger'], 'Les éléments d’un objet remplissent des fonctions techniques complémentaires.'), TF('Le mouvement d’un objet se décrit par rapport à un repère ou un observateur.', true, 'Un passager assis est immobile par rapport à son siège mais se déplace par rapport au sol quand le train roule.'), MC('Pour comparer deux prototypes, que faut-il faire ?', 'Définir les mêmes critères et des conditions de test comparables', ['Changer toutes les conditions au hasard', 'Choisir uniquement la couleur', 'Ignorer le besoin de départ'], 'Une comparaison utile demande des essais organisés.'), FREE('Imagine un objet pour transporter trois livres sous la pluie. Décris le besoin et deux contraintes.', 'Le besoin est de transporter des livres. Les contraintes peuvent être de les protéger de l’eau, de supporter leur masse et d’être facile à porter. Je propose une solution et une façon de la tester.', {
  practice: true
})]);
chapter('sciences', 'La Terre et le système solaire', ['La Terre est une planète qui tourne autour du Soleil.', 'La rotation de la Terre explique l’alternance du jour et de la nuit.', 'Les saisons sont liées à l’inclinaison de l’axe terrestre et à la révolution autour du Soleil.'], [MC('Qu’est-ce que le Soleil ?', 'Une étoile', ['Une planète', 'Un satellite artificiel', 'Une comète'], 'Le Soleil émet sa propre lumière : c’est une étoile.'), MC('Qu’est-ce qui explique principalement l’alternance jour-nuit sur Terre ?', 'La rotation de la Terre sur elle-même', ['La disparition du Soleil chaque soir', 'La Lune qui cache toujours le Soleil', 'L’arrêt de la Terre'], 'La partie tournée vers le Soleil est éclairée ; l’autre est dans la nuit.'), PAIR('Relie le mouvement à sa durée approximative.', ['Rotation de la Terre', 'Révolution de la Terre autour du Soleil'], ['Un jour', 'Une année'], 'La Terre effectue deux mouvements différents : tourner sur elle-même et autour du Soleil.'), TF('Les saisons sont dues seulement à la distance entre la Terre et le Soleil.', false, 'Elles dépendent surtout de l’inclinaison de l’axe terrestre, qui fait varier l’éclairement et la durée du jour au cours de l’année.'), MC('Pourquoi la Lune est-elle visible ?', 'Elle renvoie une partie de la lumière du Soleil.', ['Elle est une lampe fabriquée.', 'Elle produit toujours sa propre lumière comme une étoile.', 'Elle est un nuage.'], 'La Lune est un satellite naturel qui réfléchit la lumière solaire.'), FREE('Explique avec une lampe et une balle comment représenter le jour et la nuit.', 'La lampe représente le Soleil et la balle la Terre. Un côté est éclairé et l’autre est dans l’ombre. En faisant tourner la balle sur elle-même, un point passe du jour à la nuit.', {
  practice: true
})]);
chapter('sciences', 'Météo, climat et risques naturels', ['La météo décrit l’état de l’atmosphère à un moment et dans un lieu.', 'Le climat se décrit à partir de mesures et de tendances sur de longues durées.', 'Séismes, éruptions et inondations sont des phénomènes naturels dont les risques dépendent aussi des populations et des aménagements.'], [MC('Quelle phrase parle de météo ?', 'Il pleut ce matin dans cette ville.', ['Les hivers de cette région sont généralement doux.', 'Le climat est étudié sur de longues périodes.', 'Cette région a un climat méditerranéen.'], 'La phrase décrit un temps observé à un moment précis.'), PAIR('Relie l’instrument à la mesure.', ['Thermomètre', 'Pluviomètre', 'Anémomètre'], ['Température', 'Quantité de pluie', 'Vitesse du vent'], 'Chaque instrument mesure une grandeur donnée.'), TF('Une journée froide suffit à montrer que le climat ne se réchauffe pas.', false, 'Le climat se décrit sur de longues durées et de vastes ensembles de données, pas à partir d’une seule journée.'), MC('Quel geste fait partie de la prévention d’un risque d’inondation ?', 'Connaître les consignes locales et les zones exposées', ['Ignorer toutes les alertes', 'Traverser volontairement un courant fort', 'Jeter des déchets dans les évacuations'], 'Prévenir un risque implique de s’informer, de limiter l’exposition et de suivre les consignes.'), MC('Un séisme correspond principalement à…', 'des secousses du sol liées à une rupture en profondeur', ['une pluie de glace', 'la rotation visible du Soleil', 'un simple changement de saison'], 'Les mouvements en profondeur libèrent de l’énergie qui se propage sous forme d’ondes.'), FREE('Quelle différence fais-tu entre observer le temps pendant une semaine et étudier le climat ?', 'Une semaine de relevés décrit la météo de quelques jours. Étudier le climat demande des séries de mesures sur de longues périodes et leur comparaison.')]);
chapter('sciences', 'Le corps, les aliments et la respiration', ['Le corps a besoin de matière et d’énergie pour grandir et fonctionner.', 'La digestion transforme les aliments ; des nutriments passent dans le sang au niveau de l’intestin.', 'La respiration permet des échanges de gaz, et la circulation sanguine transporte notamment dioxygène et nutriments.'], [ORDER('Replace ces organes dans le trajet simplifié des aliments.', ['Bouche', 'Œsophage', 'Estomac', 'Intestin grêle', 'Gros intestin'], 'Les aliments avancent dans le tube digestif et y subissent des transformations.'), MC('Où de nombreux nutriments passent-ils dans le sang ?', 'Au niveau de l’intestin grêle', ['Dans les cheveux', 'Dans les ongles', 'Dans les oreilles'], 'La paroi de l’intestin grêle permet l’absorption de nombreux nutriments.'), PAIR('Relie l’organe à son rôle principal décrit.', ['Poumons', 'Cœur', 'Estomac'], ['Participer aux échanges de gaz avec l’air', 'Propulser le sang', 'Participer à la digestion des aliments'], 'Ces organes assurent des fonctions différentes et complémentaires.'), TF('Le corps continue de fonctionner et d’utiliser de l’énergie pendant le sommeil.', true, 'La respiration, la circulation et de nombreuses autres fonctions se poursuivent pendant le sommeil.'), MC('Pour une alimentation variée, quel principe est pertinent ?', 'Varier les aliments et les familles d’aliments sur la durée', ['Manger toujours un seul aliment', 'Supprimer toute eau', 'Choisir seulement selon les publicités'], 'La variété permet d’apporter des éléments différents au corps.'), FREE('Explique un lien entre digestion, respiration et circulation.', 'La digestion fournit des nutriments, la respiration apporte du dioxygène au sang et la circulation les transporte vers les organes qui en ont besoin pour fonctionner.')]);
chapter('sciences', 'Cycles de vie et reproduction', ['Les êtres vivants ont des cycles de vie différents.', 'Chez de nombreuses plantes à fleurs, une pollinisation puis une fécondation permettent la formation de graines.', 'La reproduction permet l’apparition de nouveaux individus ; la croissance transforme un individu déjà né.'], [MC('Quelle différence existe entre grandir et se reproduire ?', 'Grandir transforme un individu ; se reproduire donne de nouveaux individus.', ['Ce sont toujours les mêmes actions.', 'Seules les pierres grandissent.', 'Se reproduire signifie forcément se déplacer.'], 'Croissance et reproduction sont deux phénomènes distincts.'), ORDER('Place les étapes simplifiées d’une plante à fleurs.', ['Une graine germe', 'La plante grandit', 'La plante produit des fleurs', 'Après pollinisation et fécondation, de nouvelles graines se forment'], 'Toutes les graines ne germent pas, mais elles peuvent donner de nouvelles plantes si les conditions conviennent.'), MC('La pollinisation correspond au transport…', 'de pollen vers une partie réceptrice de la fleur', ['de tous les animaux vers la mer', 'de sable vers la Lune', 'd’eau vers les nuages seulement'], 'Le pollen peut être transporté par le vent ou des animaux, selon les plantes.'), TF('Une bouture peut donner une nouvelle plante sans graine.', true, 'Certaines plantes peuvent se multiplier à partir d’une partie de la plante : c’est une reproduction végétative.'), PAIR('Relie l’exemple au développement.', ['Papillon', 'Poule', 'Haricot'], ['Œuf, chenille, chrysalide, adulte', 'Œuf, poussin, adulte', 'Graine, jeune plante, plante adulte'], 'Les cycles ont des étapes communes et des différences importantes.'), FREE('Compare le cycle du papillon et celui de la poule.', 'Les deux commencent par un œuf et donnent un adulte capable de se reproduire. Le papillon passe par une chenille et une chrysalide, tandis que le poussin ressemble davantage à l’adulte.')]);
chapter('sciences', 'Programmer, tester et réparer', ['Un algorithme est une suite d’instructions organisées pour réaliser une tâche.', 'Un programme peut utiliser une répétition et une condition.', 'Tester, repérer une erreur et modifier fait partie de la conception d’un objet ou d’un programme.'], [MC('Quel exemple est une instruction précise pour un robot sur quadrillage ?', 'Avance de 3 cases.', ['Va quelque part.', 'Sois gentil.', 'Fais ce que je pense.'], 'Une instruction doit indiquer une action exécutable et suffisamment précise.'), NUM('Un robot répète 4 fois « avance de 2 cases ». Combien de cases parcourt-il sans tourner ?', 8, '4 × 2 = 8 cases.', 'cases'), MC('À quoi sert une condition « si… alors… » ?', 'À choisir une action selon une situation', ['À tout répéter sans choix', 'À supprimer toutes les instructions', 'À produire du courant électrique'], 'Par exemple : si un obstacle est détecté, alors s’arrêter.'), ORDER('Organise une démarche de programmation.', ['Définir le résultat attendu', 'Écrire les instructions', 'Tester le programme', 'Corriger les erreurs puis tester de nouveau'], 'Les tests aident à comparer le résultat obtenu au résultat attendu.'), TF('Un premier essai qui ne fonctionne pas oblige à abandonner le projet.', false, 'On peut analyser l’erreur et améliorer le programme ou le prototype.'), FREE('Programme sur papier un robot qui dessine un carré de 2 cases de côté.', 'Répéter quatre fois : avancer de 2 cases, puis tourner d’un quart de tour dans le même sens. Je vérifie que le robot revient à son point de départ.', {
  practice: true
})]);
chapter('francais', 'Attribut, compléments du nom et participes', ['Un attribut du sujet donne une caractéristique du sujet avec un verbe comme être ou sembler.', 'Un complément du nom apporte une précision sur un nom, souvent avec une préposition.', 'Avec avoir, le participe passé s’accorde avec le COD quand celui-ci est placé avant, dans les cas étudiés.'], [MC('Dans « La rivière est calme », « calme » est…', 'attribut du sujet', ['COD', 'sujet', 'complément du nom'], 'Le mot calme caractérise la rivière grâce au verbe être.'), MC('Dans « un sac de randonnée », quel groupe est complément du nom « sac » ?', 'de randonnée', ['un', 'sac', 'aucun'], '« De randonnée » précise le nom sac.'), MC('Dans « une longue route », « longue » est…', 'un adjectif épithète du nom route', ['un verbe', 'un COD', 'un déterminant'], 'L’adjectif est directement associé au nom dans le groupe nominal.'), MC('Complète : « Les pommes que j’ai … sont mûres. »', 'cueillies', ['cueilli', 'cueillie', 'cueillir'], 'Le COD « que », qui reprend les pommes, est placé avant « ai cueillies ». Le participe s’accorde au féminin pluriel.'), TF('Dans « J’ai cueilli les pommes », le participe passé s’accorde avec « les pommes » placé après.', false, 'Avec avoir, le participe ne s’accorde pas avec le COD placé après dans cette phrase : « cueilli ».'), PAIR('Relie les groupes à leur rôle.', ['La forêt est « sombre ».', 'une forêt « de chênes »', 'une « grande » forêt'], ['Attribut du sujet', 'Complément du nom', 'Épithète'], 'Attribut, complément du nom et épithète sont des fonctions différentes.'), MC('Complète : « Les filles semblent … ».', 'fatiguées', ['fatigué', 'fatiguée', 'fatigués'], 'L’attribut s’accorde avec le sujet féminin pluriel les filles.'), FREE('Enrichis « une maison » avec un adjectif et un complément du nom, puis repère-les.', 'Par exemple : « une petite maison de pierre ». Petite est un adjectif épithète ; de pierre est un complément du nom maison.')]);
chapter('francais', 'Le plus-que-parfait et l’antériorité', ['Le plus-que-parfait se forme avec avoir ou être à l’imparfait, puis un participe passé.', 'Il peut exprimer une action accomplie avant une autre action passée.', 'La négation se place autour de l’auxiliaire : je n’avais pas fini.'], [MC('Quelle forme est au plus-que-parfait ?', 'Nous avions terminé', ['Nous terminons', 'Nous terminerons', 'Nous avons terminé'], 'Avions est l’auxiliaire avoir à l’imparfait, suivi de terminé.'), MC('Complète : « Elle … avant notre arrivée. »', 'était partie', ['est partir', 'avait partie', 'sera partir'], 'Partir se conjugue avec être : elle était partie.'), MC('Dans « Quand je suis arrivé, il avait fermé la porte », quelle action a lieu en premier ?', 'Il ferme la porte.', ['J’arrive.', 'Elles sont forcément simultanées.', 'Aucune action n’a lieu.'], 'Le plus-que-parfait « avait fermé » situe la fermeture avant l’arrivée.'), PAIR('Relie chaque temps à sa forme.', ['Présent', 'Passé composé', 'Plus-que-parfait'], ['Je finis.', 'J’ai fini.', 'J’avais fini.'], 'Le plus-que-parfait se distingue par l’auxiliaire à l’imparfait.'), TF('« Nous étions venus » contient un auxiliaire à l’imparfait.', true, 'Étions est une forme du verbe être à l’imparfait.'), MC('Quelle négation est correcte ?', 'Je n’avais pas compris.', ['Je avais compris ne pas.', 'Je ne pas avais compris.', 'Je n’avais compris pas.'], 'Ne et pas encadrent l’auxiliaire avais.'), MC('Complète : « Les élèves étaient … avant la sonnerie. »', 'arrivés', ['arrivé', 'arrivée', 'arriver'], 'Avec être, le participe passé s’accorde avec les élèves au masculin pluriel dans cette phrase.'), FREE('Écris une phrase où une action au plus-que-parfait précède une autre action passée.', 'Quand nous sommes entrés, Nox avait déjà préparé les cartes. Préparer les cartes a lieu avant entrer.')]);
chapter('maths', 'Égalités, suites et algorithmes', ['Le signe égal signifie que deux expressions ont la même valeur.', 'Une case vide peut représenter un nombre à trouver.', 'Dans une suite ou un programme, identifie la règle et teste-la.'], [NUM('Trouve le nombre manquant : 17 + □ = 42.', 25, '42 − 17 = 25. On vérifie : 17 + 25 = 42.'), NUM('Trouve le nombre manquant : □ × 6 = 54.', 9, '6 × 9 = 54.'), NUM('Continue la suite : 5, 10, 15, 20, …', 25, 'On ajoute 5 à chaque étape : le nombre suivant est 25.'), NUM('Un motif a 3 carrés, puis 6, puis 9. Si la même règle continue, combien au quatrième motif ?', 12, 'On ajoute 3 carrés à chaque étape : 9 + 3 = 12.'), TF('8 + 4 = 7 + 5 est une égalité vraie.', true, 'Les deux côtés valent 12.'), ORDER('Range les étapes du programme : choisir 4, ajouter 3, multiplier le résultat par 2.', ['Choisir le nombre 4', 'Ajouter 3 pour obtenir 7', 'Multiplier 7 par 2', 'Annoncer le résultat 14'], 'L’ordre des instructions change le résultat.'), NUM('Un robot répète 3 fois « avance de 2 cases ». Il ne tourne pas. Combien de cases parcourt-il ?', 6, '3 × 2 = 6 cases.', 'cases'), FREE('Explique comment vérifier une égalité avec un nombre manquant.', 'Je remplace la case par le nombre trouvé et calcule séparément les deux côtés. Ils doivent donner la même valeur.')]);

// ANGLAIS — situations A1 ; les productions orales sont autoévaluées.
chapter('anglais', 'Hello! Se présenter', ['Hello signifie bonjour. My name is… permet de donner son prénom.', 'Pour demander un prénom : What’s your name? Pour demander l’âge : How old are you?', 'On peut s’entraîner à voix haute ; l’application ne note pas la prononciation.'], [MC('Comment dire « Bonjour » en anglais ?', 'Hello', ['Goodbye', 'Thank you', 'Sorry'], 'Hello est une salutation.'), MC('On te demande « What’s your name? ». Que peux-tu répondre ?', 'My name is Alex.', ['I am ten years old.', 'It is blue.', 'It is Monday.'], 'La question porte sur le prénom.'), MC('Comment dire « J’ai dix ans » ?', 'I am ten years old.', ['I have ten years.', 'I is ten years old.', 'I am ten books.'], 'En anglais, on utilise le verbe be pour l’âge : I am ten years old.'), PAIR('Associe les expressions.', ['Thank you', 'Please', 'Goodbye'], ['Merci', 'S’il te plaît', 'Au revoir'], 'Ces expressions permettent d’échanger poliment.'), TF('« How old are you? » demande l’âge.', true, 'On peut répondre « I am ten years old », en adaptant le nombre à son âge.'), FREE('Présente-toi en anglais avec ton prénom et un âge réel ou inventé.', 'Par exemple : « Hello! My name is Alex. I am ten years old. » Je peux utiliser une identité imaginaire pour m’entraîner.', {
  practice: true
})]);
chapter('anglais', 'À l’école : écouter et agir', ['Les consignes de classe utilisent des verbes d’action : listen, read, write, look.', 'Stand up signifie levez-vous ; sit down signifie asseyez-vous.', 'Un mot connu et le contexte aident à comprendre une consigne courte.'], [MC('« Open your book » signifie…', 'Ouvre ton livre.', ['Ferme la porte.', 'Dessine un arbre.', 'Compte jusqu’à dix.'], 'Open = ouvrir ; book = livre.'), PAIR('Relie la consigne à son sens.', ['Listen', 'Read', 'Write'], ['Écoute', 'Lis', 'Écris'], 'Les verbes indiquent ce qu’il faut faire.'), MC('Quel objet est « a pencil » ?', 'Un crayon', ['Une règle', 'Une table', 'Une fenêtre'], 'Pencil désigne un crayon.'), SORT('Classe les mots.', ['book', 'chair', 'pencil', 'table'], ['Matériel pour lire ou écrire', 'Mobilier'], [0, 1, 0, 1], 'Book et pencil sont du matériel ; chair et table sont du mobilier.'), TF('« Sit down » veut dire « Lève-toi ».', false, 'Sit down signifie assieds-toi. Stand up signifie lève-toi.'), FREE('Joue trois consignes en anglais avec un partenaire : « Stand up », « Open your book », « Sit down ».', 'Je comprends les actions et peux les réaliser dans l’ordre, en demandant de répéter si besoin : « Can you repeat, please? »', {
  practice: true
})]);
chapter('anglais', 'Nombres, dates et météo', ['Les nombres servent à dire son âge, une quantité ou une heure simple.', 'Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday sont les jours de la semaine.', 'It is sunny, rainy ou cloudy permet de décrire le temps.'], [MC('Quel nombre est « twelve » ?', '12', ['20', '2', '30'], 'Twelve signifie douze.'), MC('Quel jour vient après Monday ?', 'Tuesday', ['Sunday', 'Friday', 'Saturday'], 'Dans l’ordre des jours : Monday puis Tuesday.'), PAIR('Associe la météo.', ['It is sunny.', 'It is rainy.', 'It is cloudy.'], ['Il y a du soleil.', 'Il pleut.', 'Le ciel est nuageux.'], 'Sunny vient de sun ; rainy de rain ; cloudy de cloud.'), MC('« It is three o’clock » signifie…', 'Il est trois heures.', ['Il est treize heures trente.', 'Nous sommes trois.', 'Il y a trois livres.'], 'O’clock indique une heure exacte.'), ORDER('Remets les jours dans l’ordre, du début à la fin de cette période.', ['Wednesday', 'Thursday', 'Friday', 'Saturday'], 'Wednesday = mercredi, Thursday = jeudi, Friday = vendredi, Saturday = samedi.'), FREE('Dis en anglais un jour de la semaine et une phrase de météo.', 'Par exemple : « Today is Monday. It is sunny. » Je peux changer le jour et la météo pour qu’ils correspondent à la situation.', {
  practice: true
})]);
chapter('anglais', 'Famille, maison et description', ['He et she permettent de reprendre une personne ; they reprend plusieurs personnes.', 'There is annonce un élément ; there are en annonce plusieurs.', 'Les adjectifs usuels décrivent la taille, la couleur ou l’aspect.'], [MC('« My sister » signifie…', 'Ma sœur', ['Mon frère', 'Mon père', 'Mon cousin'], 'Sister = sœur.'), MC('Complète : « There … two cats. »', 'are', ['is', 'am', 'be'], 'Avec deux chats, le groupe est pluriel : there are.'), PAIR('Relie les pièces de la maison.', ['Kitchen', 'Bedroom', 'Bathroom'], ['Cuisine', 'Chambre', 'Salle de bains'], 'Ces noms permettent de décrire un logement.'), MC('Comment dire « un petit chien noir » ?', 'A small black dog', ['A dog black small', 'An small dog black', 'A small black house'], 'En anglais, les adjectifs sont placés avant le nom dans cet exemple.'), TF('« They are happy » peut parler de plusieurs personnes.', true, 'They est un pronom pluriel dans cette phrase et are est la forme du verbe be.'), FREE('Décris une pièce imaginaire avec « There is » et « There are ».', 'Par exemple : « There is a bed. There are two chairs. » Je distingue un seul élément de plusieurs.', {
  practice: true
})]);
chapter('anglais', 'Goûts, repas et activités', ['I like… et I don’t like… expriment des goûts.', 'Do you like…? permet de poser une question sur un goût.', 'Can et can’t parlent notamment de ce que l’on sait faire.'], [MC('Comment dire « J’aime les pommes » ?', 'I like apples.', ['I likes apples.', 'I am apples.', 'I can apple.'], 'Avec I au présent, on utilise like sans s.'), MC('À « Do you like carrots? », quelle réponse positive convient ?', 'Yes, I do.', ['Yes, I am.', 'No, I can’t.', 'It is blue.'], 'La réponse courte reprend do : Yes, I do.'), PAIR('Associe les aliments.', ['Bread', 'Water', 'Cheese'], ['Pain', 'Eau', 'Fromage'], 'Ces mots sont fréquents dans les échanges sur les repas.'), MC('« I can swim » signifie…', 'Je sais nager.', ['Je dois dormir.', 'Je n’aime pas lire.', 'J’ai une maison.'], 'Can exprime ici une capacité.'), TF('« I don’t like fish » exprime qu’on n’aime pas le poisson.', true, 'Don’t like est la forme négative utilisée avec I au présent.'), FREE('Fais un mini-dialogue en anglais avec une question sur les goûts et une réponse.', 'Exemple : « Do you like apples? — Yes, I do. » Ou « No, I don’t. » Je peux changer l’aliment et respecter la réponse choisie.', {
  practice: true
})]);
chapter('anglais', 'Se repérer et découvrir des cultures', ['Left, right et straight on aident à donner une direction.', 'Des lieux, fêtes et histoires permettent de découvrir des cultures anglophones diverses.', 'On évite de supposer que tous les habitants d’un pays ont les mêmes habitudes.'], [MC('« Turn left » signifie…', 'Tourne à gauche.', ['Tourne à droite.', 'Arrête de lire.', 'Assieds-toi.'], 'Left = gauche ; right = droite.'), PAIR('Associe le lieu à son nom anglais.', ['Library', 'School', 'Park'], ['Bibliothèque', 'École', 'Parc'], 'Library est un faux ami : ce mot ne signifie pas librairie.'), MC('Quelle ville est la capitale du Royaume-Uni ?', 'London', ['Dublin', 'New York', 'Sydney'], 'London est le nom anglais de Londres.'), TF('Toutes les personnes qui parlent anglais vivent au Royaume-Uni.', false, 'On parle anglais dans de nombreux pays et dans des situations internationales.'), MC('« Where is the library? » demande…', 'Où est la bibliothèque ?', ['Combien coûte le livre ?', 'Quel âge as-tu ?', 'Aimes-tu nager ?'], 'Where demande un lieu.'), FREE('Sur une feuille, dessine une école et une bibliothèque. Donne un petit itinéraire en anglais.', 'Par exemple : « Go straight on. Turn right. The library is on your left. » Je vérifie que les directions correspondent à mon dessin.', {
  practice: true
})]);

// EMC — vivre en République, institutions, droits, égalité, médias.
chapter('emc', 'Vivre en République', ['Les règles communes protègent les libertés et organisent la vie collective.', 'Liberté, égalité et fraternité sont des valeurs à mettre en pratique.', 'La laïcité garantit notamment la liberté de conscience et la neutralité de l’État.'], [MC('Quelle est la devise de la République française ?', 'Liberté, Égalité, Fraternité', ['Vitesse, Force, Richesse', 'Silence, Secret, Hasard', 'Tous pareils en tout'], 'La devise exprime des valeurs communes, pas l’obligation d’avoir les mêmes goûts.'), MC('Être égaux en droits signifie…', 'avoir la même dignité et les mêmes droits fondamentaux', ['avoir tous la même opinion', 'porter toujours les mêmes vêtements', 'interdire les différences'], 'L’égalité des droits respecte la diversité des personnes.'), PAIR('Associe la valeur à un exemple.', ['Liberté', 'Égalité', 'Fraternité'], ['Exprimer une opinion dans le respect des droits d’autrui', 'Appliquer la même règle à chacun', 'Aider une personne en difficulté'], 'Les valeurs s’observent dans des actes quotidiens.'), TF('La liberté d’expression autorise toutes les violences et les discriminations.', false, 'Les libertés s’exercent dans le respect des droits d’autrui et des lois.'), MC('La liberté de conscience protège…', 'le droit d’avoir une conviction religieuse ou de ne pas en avoir', ['l’obligation d’adopter une même religion', 'l’interdiction de réfléchir', 'le droit d’imposer sa croyance aux autres'], 'La neutralité de l’État permet de respecter les convictions de chacun.'), FREE('Propose une action de fraternité à l’école et explique-la.', 'Je peux proposer d’aider un camarade isolé à rejoindre une activité, en respectant son choix. La fraternité se traduit par la solidarité et le souci des autres.')]);
chapter('emc', 'Citoyens et institutions', ['Les citoyens participent à la vie démocratique par le vote et d’autres formes d’engagement.', 'Le Parlement vote la loi ; le gouvernement la met en œuvre.', 'La commune dispose d’un conseil municipal et d’un maire qui agissent pour la vie locale.'], [MC('Quelle institution vote les lois nationales en France ?', 'Le Parlement', ['Le club de sport', 'Une seule classe de CM2', 'La météo nationale'], 'Le Parlement comprend l’Assemblée nationale et le Sénat.'), MC('Que fait un conseil municipal ?', 'Il délibère sur des affaires de la commune.', ['Il décide du mouvement des planètes.', 'Il écrit tous les romans.', 'Il remplace toutes les écoles du monde.'], 'Les décisions municipales concernent notamment des équipements et services locaux.'), PAIR('Relie la fonction au rôle.', ['Députés et sénateurs', 'Gouvernement', 'Conseil municipal'], ['Débattre et voter les lois', 'Conduire la politique du pays et faire appliquer les lois', 'Prendre des décisions pour la commune'], 'Ces institutions ont des rôles différents.'), TF('Un enfant peut participer à un projet collectif sans avoir le droit de vote aux élections nationales.', true, 'Il peut débattre, proposer des idées et participer à des projets ou à certains conseils d’enfants.'), MC('Lors d’un vote de délégués en classe, pourquoi garder un dépouillement vérifiable ?', 'Pour établir un résultat transparent et accepté', ['Pour choisir au hasard après coup', 'Pour cacher le nombre de voix', 'Pour avantager un ami'], 'Des règles connues et respectées rendent le vote plus juste.'), FREE('Propose un projet pour ton école et indique comment en discuter collectivement.', 'Je présente le besoin, écoute les objections, cherche des solutions et propose une décision avec des règles communes. Je peux demander l’aide d’un adulte pour sa réalisation.')]);
chapter('emc', 'Droits, devoirs et nationalité', ['Chaque enfant possède des droits, dont l’éducation, la protection et l’accès aux soins.', 'Un droit n’empêche pas d’avoir des devoirs envers les autres.', 'La nationalité peut s’acquérir de différentes façons prévues par la loi ; elle ne se déduit pas d’une apparence.'], [MC('Quel est un droit de l’enfant ?', 'Être protégé contre les violences', ['Pouvoir frapper les autres', 'Être privé d’instruction', 'Travailler dans n’importe quelles conditions'], 'La protection est un droit pour tous les enfants.'), MC('Quel comportement respecte le droit des autres à apprendre ?', 'Laisser chacun écouter et poser des questions', ['Empêcher un camarade de lire', 'Se moquer de toute erreur', 'Détruire le matériel commun'], 'Nos comportements influencent l’exercice des droits d’autrui.'), TF('On peut connaître la nationalité d’une personne uniquement en regardant sa couleur de peau.', false, 'L’apparence ne permet pas de connaître une nationalité. La nationalité est un lien juridique, pas une couleur de peau.'), SORT('Classe les exemples.', ['Recevoir une instruction', 'Respecter les autres', 'Être protégé', 'Prendre soin du matériel prêté'], ['Un droit', 'Un devoir ou une responsabilité'], [0, 1, 0, 1], 'Droits et responsabilités permettent de vivre ensemble.'), MC('À qui les droits fondamentaux de la personne doivent-ils être reconnus ?', 'À toute personne', ['Seulement aux plus riches', 'Seulement aux meilleurs élèves', 'Seulement à ceux qui pensent comme nous'], 'La dignité et les droits fondamentaux ne dépendent pas des résultats ou de la richesse.'), FREE('Explique pourquoi une règle de classe peut protéger une liberté.', 'La règle de ne pas interrompre protège la possibilité de s’exprimer et d’être entendu. Une règle juste sert la vie collective et les droits de chacun.')]);
chapter('emc', 'Égalité, respect et lutte contre les discriminations', ['Un stéréotype attribue des caractéristiques à tout un groupe sans tenir compte des personnes.', 'Discriminer, c’est traiter défavorablement une personne selon certains critères, plutôt que selon sa situation réelle.', 'On peut agir en refusant les moqueries, en soutenant la personne visée et en demandant de l’aide.'], [MC('Quelle phrase est un stéréotype ?', 'Les filles ne peuvent pas être scientifiques.', ['Cette scientifique travaille dans un laboratoire.', 'Chacun peut apprendre les sciences.', 'Cette expérience demande de la patience.'], 'La phrase attribue une incapacité à tout un groupe en fonction du genre.'), MC('Un camarade est exclu d’un jeu à cause de son handicap. Que faire ?', 'Chercher une adaptation et alerter un adulte si nécessaire', ['Se moquer aussi', 'Dire que c’est toujours normal', 'Cacher la situation'], 'L’inclusion demande de prendre en compte les besoins et de refuser l’exclusion injuste.'), TF('Filles et garçons ont la même dignité et peuvent développer des talents variés.', true, 'Les goûts et les capacités ne se résument pas au genre.'), PAIR('Associe l’attitude à son sens.', ['Écouter le ressenti d’un autre', 'Aider sans humilier', 'Refuser une généralisation sur un groupe'], ['Faire preuve d’empathie', 'Agir avec solidarité', 'Questionner un stéréotype'], 'Le respect se traduit par l’écoute, l’entraide et l’esprit critique.'), MC('Quand on découvre une erreur dans une idée que l’on avait sur un groupe, on peut…', 'la remettre en question et apprendre', ['la garder à tout prix', 'insulter ceux qui expliquent', 'refuser de regarder des faits'], 'Réfléchir permet de dépasser les préjugés.'), FREE('Imagine une façon de rendre un jeu plus accueillant pour des participants différents.', 'Je peux adapter les règles, expliquer les consignes et répartir les rôles pour que chacun puisse contribuer. Je demande aux personnes ce dont elles ont besoin.')]);
chapter('emc', 'Information, médias et esprit critique', ['Une information se vérifie en recherchant sa source, sa date et d’autres confirmations.', 'Une publicité cherche à influencer ; une opinion exprime un point de vue.', 'Une image ou un message partagé peut être sorti de son contexte ou modifié.'], [MC('Avant de partager une information surprenante, il vaut mieux…', 'vérifier l’auteur, la date et d’autres sources fiables', ['la transmettre immédiatement', 'croire qu’un grand titre suffit', 'supprimer toutes les questions'], 'La vérification limite la diffusion d’erreurs.'), MC('Quel message relève d’une publicité ?', 'Achète ce jeu : offre exceptionnelle !', ['Le musée ouvre à 10 h selon son site.', 'La séance commence à 14 h.', 'Il y a 24 élèves inscrits dans cette liste.'], 'Le message cherche à déclencher un achat.'), TF('Une photo réelle peut être utilisée avec une légende trompeuse.', true, 'Le contexte, la date et le lieu peuvent être modifiés dans le commentaire même si l’image est réelle.'), ORDER('Organise une petite vérification.', ['Identifier ce que le message affirme', 'Chercher sa source et sa date', 'Comparer avec d’autres sources pertinentes', 'Décider si l’information est assez vérifiée pour être partagée'], 'On vérifie avant de diffuser.'), MC('Que faire si une information reste incertaine ?', 'Dire qu’on ne sait pas encore et demander de l’aide pour vérifier', ['Inventer une preuve', 'Affirmer qu’elle est vraie à coup sûr', 'Attaquer celui qui doute'], 'Reconnaître une incertitude est une démarche rigoureuse.'), FREE('Explique la différence entre « Ce livre compte 100 pages » et « Ce livre est formidable ».', 'La première phrase donne une information vérifiable sur un exemplaire du livre. La seconde exprime un jugement personnel qui peut varier selon les lecteurs.')]);

// ARTS — pratiques ouvertes et repères ; l'application ne juge pas une création.
chapter('arts', 'Formes, couleurs et composition', ['Une composition organise des formes, couleurs et espaces pour produire un effet.', 'Les couleurs, contrastes et gestes peuvent suggérer des émotions sans avoir un sens unique.', 'On peut expérimenter avec plusieurs outils, matériaux et supports.'], [MC('En arts plastiques, « composer » signifie notamment…', 'organiser les éléments d’une création', ['copier sans réfléchir toutes les images', 'compter seulement les crayons', 'chercher une réponse unique pour toute œuvre'], 'La place, la taille et les rapports entre éléments construisent une composition.'), PAIR('Associe le mot à sa description.', ['Contraste', 'Texture', 'Cadrage'], ['Différence marquée entre des éléments', 'Aspect ou effet de surface', 'Choix de ce qui entre dans l’image'], 'Ce vocabulaire aide à décrire et créer.'), TF('Deux personnes peuvent ressentir des émotions différentes face aux mêmes couleurs.', true, 'La perception dépend du contexte, de l’expérience et des associations de chacun.'), MC('Pour rendre un petit élément très visible, on peut…', 'créer un contraste avec ce qui l’entoure', ['le rendre obligatoirement invisible', 'supprimer tout le support', 'interdire toutes les couleurs'], 'Un contraste de couleur, de valeur ou de forme peut attirer l’attention.'), FREE('Crée un paysage imaginaire avec des formes géométriques. Choisis une zone qui attire le regard.', 'Je compose plusieurs formes, varie leur taille et choisis des couleurs. Je peux expliquer comment ma composition attire le regard vers une zone.', {
  practice: true,
  studio: true
}), FREE('Explique un choix de couleur ou de forme dans ta création.', 'Je nomme mon choix et l’effet recherché. Par exemple, un petit rond clair sur un fond sombre peut devenir un point lumineux. Plusieurs intentions sont possibles.', {
  practice: true
})]);
chapter('arts', 'Raconter avec des images et des matières', ['Une image peut raconter un moment ; plusieurs images peuvent former une séquence.', 'Le point de vue et le cadrage changent ce que voit le spectateur.', 'Le collage, l’assemblage et le modelage permettent de jouer avec les matières et les volumes.'], [MC('Dans une bande dessinée, une suite de cases peut…', 'raconter plusieurs moments d’une action', ['obligatoirement décrire une seule couleur', 'remplacer toute lecture par du calcul', 'avoir toujours la même taille'], 'L’enchaînement des images construit un récit.'), PAIR('Relie la technique à son principe.', ['Collage', 'Modelage', 'Photographie'], ['Assembler des éléments sur un support', 'Façonner une matière en volume', 'Choisir un cadrage et enregistrer une image'], 'Chaque technique permet des choix et des effets différents.'), MC('Une prise de vue en plongée montre généralement le sujet…', 'depuis un point de vue situé au-dessus', ['depuis le dessous uniquement', 'sans aucun cadrage', 'toujours à la taille réelle'], 'Le point de vue influence l’impression produite.'), TF('Un objet du quotidien peut devenir un matériau dans une création artistique.', true, 'L’assemblage et le détournement utilisent parfois des objets pour leur forme, leur matière ou leur signification.'), FREE('Dessine trois cases : un personnage trouve une clé, cherche une porte, puis l’ouvre.', 'Je rends les trois étapes compréhensibles. Je peux varier les cadrages et laisser des indices entre les images.', {
  practice: true,
  studio: true
}), FREE('Choisis trois matériaux propres et sans danger, puis imagine un animal en assemblage.', 'Je choisis les matériaux pour leurs formes ou textures, prévois comment les assembler et explique mon intention. L’aide d’un adulte est utile pour tout outil qui le demande.', {
  practice: true
})]);
chapter('arts', 'Observer et situer les œuvres', ['On peut décrire une œuvre avant de l’interpréter : sujet, matériaux, formes, couleurs et organisation.', 'Un cartel donne souvent le titre, l’artiste, la date et la technique.', 'Les œuvres appartiennent à des contextes variés : architecture, peinture, sculpture, arts du spectacle et autres domaines.'], [MC('Que trouve-t-on souvent sur un cartel de musée ?', 'Le titre, l’artiste, la date et la technique', ['Le mot de passe du musée', 'Une note obligatoire pour tous les visiteurs', 'Seulement une publicité sans rapport'], 'Le cartel donne des repères utiles pour situer l’œuvre.'), PAIR('Associe les exemples aux domaines.', ['Une cathédrale', 'Une statue', 'Une représentation dansée'], ['Architecture', 'Sculpture', 'Arts du spectacle'], 'L’histoire des arts s’intéresse à des créations de domaines différents.'), MC('Quelle phrase décrit d’abord ce qu’on voit ?', 'Une grande forme rouge occupe le centre.', ['Cette œuvre est forcément mauvaise.', 'L’artiste pensait exactement comme moi.', 'Tout le monde ressent la même chose.'], 'La description s’appuie sur un élément observable.'), TF('Pour situer une œuvre dans le temps, sa date de création peut aider.', true, 'On relie cette date à des repères historiques et à son contexte.'), FREE('Choisis une œuvre dans un livre disponible chez toi. Décris-la sans commencer par « j’aime » ou « je n’aime pas ».', 'Je décris le domaine, le sujet, des formes ou couleurs et l’organisation. Ensuite je peux exprimer mon ressenti en expliquant ce qui le provoque.', {
  practice: true
}), FREE('Crée un cartel pour une de tes propres productions.', 'J’indique un titre, mon prénom ou un pseudonyme, la date et la technique. Je peux ajouter une phrase présentant mon intention.', {
  practice: true
})]);

// MUSIQUE — sons générés localement ; aucune ressource audio distante.
chapter('musique', 'Écouter et comparer les sons', ['La hauteur distingue les sons graves et aigus. L’intensité distingue les sons doux et forts.', 'Le timbre aide à reconnaître des voix ou des instruments.', 'On écoute à un volume confortable ; les exemples sonores sont facultatifs.'], [MC('Écoute les deux sons : le second est…', 'plus aigu que le premier', ['plus grave que le premier', 'de même hauteur', 'un silence'], 'Le second son a une fréquence plus élevée : il est plus aigu.', {
  tones: [220, 660],
  audioDescription: 'Version visuelle : le deuxième son vibre plus vite que le premier.'
}), MC('Quel mot décrit la vitesse d’une musique ?', 'Le tempo', ['La texture du papier', 'La masse', 'La couleur du cahier'], 'Le tempo indique la vitesse de la pulsation.'), PAIR('Associe le paramètre à la question.', ['Hauteur', 'Intensité', 'Timbre'], ['Grave ou aigu ?', 'Doux ou fort ?', 'Quelle voix ou quel instrument ?'], 'Ces paramètres permettent de comparer les sons.'), TF('Un son aigu est forcément plus fort qu’un son grave.', false, 'La hauteur et l’intensité sont indépendantes : un son aigu peut être doux.'), MC('La pulsation est…', 'un battement régulier qui sert de repère', ['toujours la mélodie entière', 'uniquement le silence final', 'le nom de tous les instruments'], 'On peut souvent marcher ou frapper régulièrement sur la pulsation.'), FREE('Frappe doucement une pulsation régulière puis invente un rythme avec tes mains.', 'Je garde un battement régulier comme repère et crée un motif de frappes et de silences. Je peux expliquer la différence entre ce repère et le rythme inventé.', {
  practice: true
})]);
chapter('musique', 'Voix, chant et instruments', ['Chanter demande d’écouter, respirer, articuler et ajuster sa voix sans forcer.', 'On peut chanter à l’unisson ou organiser des entrées différentes.', 'Des familles d’instruments se reconnaissent par la manière dont le son est produit.'], [PAIR('Relie l’instrument à sa famille dans cette classification.', ['Violon', 'Flûte', 'Tambour'], ['Cordes', 'Vents', 'Percussions'], 'Le violon utilise des cordes, la flûte l’air mis en vibration et le tambour une membrane frappée.'), MC('Chanter à l’unisson signifie…', 'chanter la même mélodie ensemble', ['chanter chacun un texte sans écouter', 'jouer seulement du tambour', 'chanter forcément très fort'], 'Les voix suivent la même ligne mélodique.'), MC('Pour chanter confortablement, il vaut mieux…', 'garder une posture disponible et ne pas forcer sa voix', ['crier jusqu’à avoir mal', 'bloquer toute respiration', 'ignorer tous les autres chanteurs'], 'La qualité d’écoute et l’aisance comptent plus que la force.'), TF('Un canon peut faire entrer plusieurs groupes à des moments différents sur une même mélodie.', true, 'Les décalages d’entrée produisent une superposition de voix.'), MC('Dans un groupe musical, écouter les autres sert notamment à…', 'coordonner les départs, le tempo et les nuances', ['les empêcher de jouer', 'ne suivre aucun repère', 'remplacer toute répétition'], 'La réalisation collective demande de l’attention aux autres.'), FREE('Chante doucement une mélodie que tu connais, puis recommence en articulant mieux le texte.', 'Je m’échauffe sans forcer, respire à des endroits utiles et écoute la justesse et la clarté des mots. Je peux faire ce travail avec un adulte ou un groupe.', {
  practice: true
})]);
chapter('musique', 'Créer, comparer et partager', ['On peut organiser une création avec un début, des motifs, des contrastes et une fin.', 'Écouter deux extraits permet de comparer tempo, instruments, caractère et organisation.', 'Pour parler d’une musique, distingue une observation d’un jugement de goût.'], [MC('Quel énoncé décrit une musique plutôt qu’un simple goût ?', 'Le tempo devient plus rapide.', ['Je n’aime pas du tout.', 'C’est la meilleure du monde.', 'Personne ne devrait l’écouter.'], 'La vitesse peut être observée, tandis qu’un goût exprime une préférence.'), ORDER('Organise un projet de paysage sonore.', ['Choisir une ambiance à évoquer', 'Chercher des sons et des silences', 'Organiser puis répéter la séquence', 'Présenter et expliquer ses choix'], 'Un projet sonore comporte une intention, des essais et une présentation.'), MC('Dans une création, le silence peut…', 'séparer, suspendre ou mettre en valeur des sons', ['être toujours une erreur', 'annuler toute expression', 'obligatoirement durer une heure'], 'Le silence est un élément de composition.'), TF('Deux interprétations d’une même chanson peuvent être différentes.', true, 'Tempo, nuances, timbres et choix d’interprétation peuvent varier.'), FREE('Avec des bruits doux et ta voix, crée une courte ambiance de forêt sans utiliser d’enregistrement.', 'Je choisis quelques sons, les organise et ajoute des silences. Je peux expliquer comment ils évoquent mon paysage.', {
  practice: true
}), FREE('Compare deux musiques que tu connais en utilisant au moins deux mots précis.', 'Je peux comparer le tempo, l’intensité, les instruments, les voix ou l’organisation. Je justifie mon ressenti avec ce que j’entends.', {
  practice: true
})]);

// EPS — connaissances et projets à réaliser dans un cadre adapté, sans chrono imposé.
chapter('eps', 'Courir, sauter et lancer', ['Une performance se prépare, s’observe et peut se mesurer pour suivre ses propres progrès.', 'Courir, sauter et lancer demandent des choix techniques adaptés au but.', 'Les activités physiques se réalisent dans un espace prévu, avec les consignes de l’adulte.'], [MC('Quel objectif aide à progresser sans se décourager ?', 'Comparer ses essais et chercher une amélioration personnelle', ['Se moquer des moins rapides', 'Refuser tous les essais', 'Choisir uniquement le plus fort'], 'Les progrès se construisent par l’observation et l’entraînement adapté.'), PAIR('Associe la performance à une mesure possible.', ['Saut en longueur', 'Course sur une distance donnée', 'Lancer en distance'], ['Distance entre la limite de départ et la réception', 'Temps pour parcourir la distance', 'Distance atteinte par l’objet'], 'La mesure doit correspondre à l’activité et respecter ses règles.'), MC('Avant un lancer en groupe, que faut-il vérifier ?', 'Que la zone de lancer est dégagée et les consignes connues', ['Que quelqu’un passe devant', 'Que personne n’écoute', 'Que l’objet est dangereux'], 'La sécurité de la zone et l’organisation du groupe sont essentielles.'), TF('On peut choisir une allure régulière adaptée plutôt que partir toujours le plus vite possible.', true, 'L’allure dépend de la durée et du but de l’activité.'), FREE('Prépare sur papier une fiche pour suivre trois essais d’un saut, à utiliser en séance avec l’adulte.', 'Je note la date, les conditions, la mesure de chaque essai et une observation technique. Je compare mes essais sans juger ma valeur personnelle.', {
  practice: true
}), FREE('Explique à un camarade une règle de sécurité avant un lancer.', 'Je rappelle d’attendre le signal, de vérifier la zone et de ne récupérer les objets que lorsque l’adulte autorise le groupe à le faire.')]);
chapter('eps', 'S’orienter et adapter ses déplacements', ['Une carte, des repères et un itinéraire aident à s’orienter.', 'Dans un environnement différent, on adapte ses déplacements et respecte les limites fixées.', 'Les activités aquatiques et de pleine nature se pratiquent dans un cadre encadré et adapté.'], [MC('En course d’orientation scolaire, avant de partir il faut…', 'connaître les limites, le but et les consignes de retour', ['partir sans prévenir', 'ignorer le plan', 'quitter la zone autorisée'], 'L’organisation permet de chercher des repères sans se mettre en difficulté.'), MC('Si tu ne reconnais plus ton chemin dans une activité encadrée, le bon réflexe est…', 'appliquer les consignes prévues et demander de l’aide', ['courir au hasard très loin', 'cacher la situation', 'quitter le groupe sans prévenir'], 'L’activité doit prévoir comment réagir en cas de doute.'), PAIR('Associe le repère à son usage.', ['Légende du plan', 'Point de départ', 'Limite de zone'], ['Comprendre les symboles', 'Savoir où commence le parcours', 'Connaître l’espace autorisé'], 'Un plan doit être lu avec ses repères et les consignes de l’activité.'), TF('Savoir nager dispense de respecter les consignes de surveillance.', false, 'La surveillance, les zones autorisées et les consignes restent indispensables.'), FREE('Trace sur papier un parcours d’orientation dans une cour imaginaire avec quatre repères.', 'Je place un départ, quatre repères, des limites et un point de retour. Les indications permettent de retrouver les lieux sans sortir de la zone.', {
  practice: true
}), FREE('Explique pourquoi on adapte son déplacement à un terrain glissant ou irrégulier.', 'On ajuste son allure, ses appuis et son attention pour garder le contrôle et respecter les consignes. On ne cherche pas la vitesse à tout prix.')]);
chapter('eps', 'Danser et composer une prestation', ['Une prestation artistique utilise le corps, l’espace, le temps et les relations entre partenaires.', 'On peut combiner des gestes, des directions, des niveaux et des rythmes.', 'Le spectateur observe avec respect et formule un retour précis.'], [MC('Pour créer un contraste dans une danse, on peut…', 'passer d’un geste lent à un geste rapide', ['faire forcément le même geste sans variation', 'interdire toute intention', 'supprimer tout espace'], 'Les contrastes de temps, d’espace et d’énergie enrichissent une composition.'), PAIR('Relie le choix à sa dimension.', ['Se déplacer en diagonale', 'Ralentir un geste', 'Danser en duo'], ['Espace', 'Temps', 'Relation entre partenaires'], 'Une composition articule plusieurs dimensions du mouvement.'), TF('Une danse doit toujours raconter la même chose à tous les spectateurs.', false, 'La création propose une intention, mais plusieurs interprétations peuvent être argumentées.'), MC('Quel retour de spectateur aide le groupe ?', 'Le passage lent rend la surprise bien visible.', ['Vous êtes nuls.', 'Je refuse d’expliquer.', 'Tout est forcément pareil.'], 'Un retour utile est précis et porte sur la prestation, sans attaquer les personnes.'), FREE('Imagine une suite de quatre gestes sur le thème « une graine grandit », réalisables dans un espace dégagé.', 'Je prévois un début, des changements de niveau et de vitesse, puis une fin lisible. Je réalise les mouvements sans difficulté acrobatique et selon les consignes du cadre de pratique.', {
  practice: true
}), FREE('Explique comment coordonner un début et une fin dans une prestation collective.', 'Le groupe peut choisir un signal commun, répéter les transitions et vérifier que chacun connaît son rôle. On s’écoute et on adapte la composition.')]);
chapter('eps', 'Coopérer et s’opposer dans les règles', ['Dans les jeux collectifs, on cherche un objectif avec des partenaires face à des adversaires.', 'Les règles protègent les participants et rendent le jeu compréhensible.', 'Joueur, arbitre et observateur ont des rôles utiles et complémentaires.'], [MC('Dans un jeu collectif, coopérer consiste notamment à…', 'agir avec ses partenaires vers un but commun', ['garder toutes les informations pour soi', 'refuser les passes', 'humilier l’adversaire'], 'La coopération repose sur la communication et l’organisation.'), MC('Que fait un arbitre ?', 'Il veille à l’application des règles avec impartialité.', ['Il change le score pour ses amis.', 'Il joue seul à la place de tous.', 'Il autorise les violences.'], 'L’arbitre aide au déroulement juste et sûr du jeu.'), PAIR('Relie le rôle à son action.', ['Joueur', 'Arbitre', 'Observateur'], ['Prendre des décisions dans l’action', 'Faire respecter les règles', 'Recueillir des informations pour progresser'], 'Changer de rôle aide à mieux comprendre l’activité.'), TF('Respecter un adversaire empêche de chercher à gagner.', false, 'On peut chercher à gagner tout en respectant les règles et les personnes.'), FREE('Propose une adaptation pour inclure un camarade ayant un besoin particulier dans un jeu de passes.', 'Je peux adapter les distances, le matériel ou les rôles avec le groupe et l’adulte. Je demande au camarade ce qui l’aide et je conserve un objectif de jeu compréhensible.'), FREE('Après un jeu, raconte une décision qui a aidé ton équipe et une amélioration possible.', 'Je décris une action précise, par exemple me démarquer pour proposer une passe. Je propose ensuite un changement observable, sans blâmer une personne.', {
  practice: true
})]);

// ÉVAR — corps, respect, relations et protection, conformément aux trois axes du CM2.
chapter('relations', 'Grandir et comprendre son corps', ['La puberté est une période de changements du corps qui ne surviennent pas au même moment chez tous.', 'Les organes reproducteurs ont des noms et des fonctions scientifiques.', 'Les règles sont un phénomène naturel ; les changements du corps ne justifient aucune moquerie.'], [MC('Les changements de la puberté…', 'ne commencent pas tous au même âge chez toutes les personnes', ['arrivent le même jour pour tout le monde', 'sont une raison de se moquer', 'rendent tous les corps identiques'], 'Le développement varie d’une personne à l’autre.'), PAIR('Relie les organes à leur fonction décrite.', ['Ovaires', 'Testicules', 'Utérus'], ['Produisent des ovules', 'Produisent des spermatozoïdes à partir de la puberté', 'Organe où peut se développer un futur bébé'], 'Ces mots décrivent des organes reproducteurs et leurs fonctions scientifiques.'), MC('Les menstruations, aussi appelées règles, sont…', 'un écoulement de sang lié au renouvellement de la muqueuse de l’utérus', ['une blessure causée par le sport dans tous les cas', 'une raison de honte', 'un phénomène qui concerne tous les organes du corps'], 'Elles font partie du fonctionnement naturel du corps et ne doivent pas être l’objet de moqueries.'), TF('On a le droit de poser des questions sur les changements du corps à un adulte de confiance.', true, 'Un adulte de confiance, un enseignant ou un professionnel de santé peut apporter des informations adaptées.'), MC('Quel comportement respecte les différences de développement ?', 'Ne pas se moquer et respecter l’intimité de chacun', ['Comparer publiquement les corps', 'Forcer quelqu’un à parler de son corps', 'Diffuser une photo privée'], 'Le respect du corps et de l’intimité s’applique à tous.'), FREE('Avec des personnages imaginaires, explique pourquoi on ne doit pas se moquer d’un changement du corps.', 'Les changements sont naturels et leur rythme varie. Chacun mérite le respect et peut garder son intimité. Je n’ai pas besoin de raconter ma situation personnelle pour l’expliquer.')]);
chapter('relations', 'Émotions, consentement et protection', ['On peut nommer des émotions et les exprimer sans violence.', 'Un accord se demande et un refus doit être respecté ; on peut changer d’avis.', 'Une violence n’est jamais la faute de la victime. On peut demander de l’aide à un adulte de confiance et continuer à en chercher si nécessaire.'], [MC('Un camarade ne veut pas qu’on le prenne dans les bras. Que faut-il faire ?', 'Respecter son refus', ['Insister jusqu’à ce qu’il cède', 'Se moquer de lui', 'Le toucher quand même'], 'Le corps de chacun doit être respecté et un refus ne se négocie pas par la pression.'), MC('Quel exemple exprime une émotion sans attaquer l’autre ?', 'Je suis triste quand je suis mis à l’écart.', ['Tu es nul pour toujours.', 'Je vais te faire du mal.', 'Tout le monde doit se taire.'], 'Nommer son ressenti aide à parler d’une situation sans violence.'), TF('Une personne peut changer d’avis après avoir d’abord dit oui à un geste.', true, 'L’accord doit rester libre ; un changement d’avis doit être respecté.'), MC('Un enfant subit des gestes ou des paroles qui lui font peur et on lui demande de garder le secret. Il peut…', 'en parler à un adulte de confiance pour être protégé', ['croire qu’il est forcément responsable', 'garder toujours le silence', 'se débrouiller seul obligatoirement'], 'Un secret qui met en danger peut être révélé pour chercher de l’aide. La victime n’est pas responsable des violences.'), PAIR('Relie la situation à une réaction respectueuse.', ['Un refus', 'Une personne mise à l’écart', 'Une situation de violence'], ['S’arrêter et respecter le choix', 'Proposer du soutien sans imposer', 'Chercher l’aide d’adultes protecteurs'], 'Respect, soutien et protection sont des repères pour agir.'), FREE('Imagine une phrase pour demander un accord et une phrase pour refuser calmement.', 'Par exemple : « Est-ce que tu veux me prendre la main ? » et « Non, je ne veux pas. » L’autre personne respecte la réponse. Il n’est pas nécessaire de raconter une expérience personnelle.')]);
chapter('relations', 'Égalité et sécurité numérique', ['Les activités, métiers et qualités ne sont pas réservés à un genre.', 'Une image privée ou une information personnelle ne se partage pas sans accord.', 'Face à un message inquiétant ou à des violences en ligne, on cherche du soutien et on ne diffuse pas davantage le contenu.'], [MC('Une personne affirme : « Ce métier est interdit aux filles. » Quelle réaction est pertinente ?', 'Questionner ce stéréotype et rappeler l’égalité des droits', ['Approuver sans réfléchir', 'Insulter toutes les personnes', 'Interdire toute question'], 'Les capacités et les choix ne se déduisent pas du genre.'), MC('Avant de publier la photo d’un camarade, il faut…', 'demander les autorisations nécessaires et respecter un refus', ['publier très vite', 'supposer que le silence vaut accord', 'la modifier pour se moquer'], 'L’image d’une personne doit être respectée et les règles de l’adulte et du cadre scolaire suivies.'), SORT('Classe les comportements en ligne.', ['Garder son mot de passe privé', 'Donner son adresse à un inconnu', 'Demander de l’aide pour un message inquiétant', 'Partager une humiliation'], ['Protège et respecte', 'Expose ou fait du tort'], [0, 1, 0, 1], 'La confidentialité et le soutien protègent ; les informations personnelles et humiliations ne se diffusent pas.'), TF('Pour s’entraîner dans une langue, on est obligé de publier son vrai nom, son adresse et sa photo.', false, 'On peut utiliser des personnages imaginaires et préserver ses informations personnelles.'), MC('Un message prétend offrir un cadeau en échange d’informations privées. Que faire ?', 'Ne pas répondre et demander l’aide d’un adulte de confiance', ['Envoyer toutes ses informations', 'Partager son mot de passe', 'Cliquer sans lire'], 'Une promesse de cadeau peut servir à obtenir des données ou à tromper.'), FREE('Écris trois règles pour une discussion de classe en ligne respectueuse et sûre.', 'Je peux proposer : ne pas publier d’informations privées, respecter les personnes, demander de l’aide pour un contenu inquiétant. Les règles sont expliquées avec l’adulte et appliquées à tous.', {
  practice: true
})]);

// Index calculés après chargement : aucune taille de programme n'est codée dans l'interface.
const QUESTIONS_BY_MISSION = new Map(MISSIONS.map((_, i) => [i, QUESTIONS.filter(q => q.mission === i)]));
const MISSIONS_BY_SUBJECT = new Map(SUBJECTS.map(s => [s.id, MISSIONS.map((m, i) => ({
  ...m,
  index: i
})).filter(m => m.subject === s.id)]));
const QUESTION_BY_ID = new Map(QUESTIONS.map(q => [q.id, q]));
for (const q of QUESTIONS) q.subject = MISSIONS[q.mission].subject;

// Supports visuels et écoutes : métadonnées d'accessibilité, aucune ressource distante.
function annotate(prompt, extra) {
  const q = QUESTIONS.find(q => q.prompt === prompt);
  if (!q) throw new Error('Activité introuvable : ' + prompt);
  Object.assign(q, extra);
}
annotate('Un disque est partagé en 8 parts égales. Trois sont coloriées. Quelle fraction est coloriée ?', {
  visual: 'fraction'
});
